window.TEXTBOOK_TEXTS = Object.assign(window.TEXTBOOK_TEXTS || {}, {"hsk2-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，您是王一飞老师的姐姐吗？","pinyin":"Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?","speaker":"白家月","vi":"Xin hỏi, chị có phải là chị gái của cô giáo Vương Nhất Phi không ạ?"},{"hanzi":"是的，你们就是她的学生吧？","pinyin":"Shì de, nǐmen jiù shì tā de xuéshēng ba?","speaker":"王一雪","vi":"Đúng rồi, các em chính là học sinh của cô ấy phải không?"},{"hanzi":"对。我是白家月，她是安妮。","pinyin":"Duì. Wǒ shì Bái Jiāyuè, tā shì Ānnī.","speaker":"白家月","vi":"Vâng. Em là Bạch Gia Nguyệt, còn bạn ấy là An Ni."},{"hanzi":"你们好，我叫王一雪。一飞给我打电话了，让我来接你们。","pinyin":"Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen.","speaker":"王一雪","vi":"Chào các em, chị tên là Vương Nhất Tuyết. Nhất Phi đã gọi điện cho chị, bảo chị đến đón các em."},{"hanzi":"谢谢您。","pinyin":"Xièxie nín.","speaker":"白家月、安妮","vi":"Cảm ơn chị ạ."},{"hanzi":"不客气。","pinyin":"Bú kèqi.","speaker":"王一雪","vi":"Không có gì."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt hỏi \"您是王一飞老师的姐姐吗？\" (\"Chị có phải là chị gái của cô giáo Vương Nhất Phi không?\") và chị ấy xác nhận \"是的\" (\"Đúng rồi\"), đồng thời giới thiệu \"我叫王一雪\" (\"Tôi tên là Vương Nhất Tuyết\"), nên người đón là Vương Nhất Tuyết – chị gái cô giáo Vương Nhất Phi.","options":["王一飞老师","王一雪，王一飞老师的姐姐","李文的朋友","陈天中"],"q":"在机场是谁接了白家月和安妮？"},{"answerIdx":1,"explanation":"Trong bài có câu \"一飞给我打电话了，让我来接你们。\" (\"Nhất Phi đã gọi điện cho tôi, bảo tôi đến đón các bạn.\"), nên lý do là vì Vương Nhất Phi đã gọi điện nhờ chị gái ra đón.","options":["因为她正好也要坐飞机。","因为王一飞给她打电话，让她来接她们。","因为白家月昨天给她发了信息。","因为她和安妮是老朋友。"],"q":"王一雪为什么来机场接她们？"}],"scene":"在机场，王一雪接到了白家月和安妮。","sceneVi":"Ở sân bay, Vương Nhất Tuyết đã đón được Bạch Gia Nguyệt và An Ni."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你们是第一次来北京吗？","pinyin":"Nǐmen shì dì-yī cì lái Běijīng ma?","speaker":"王一雪","vi":"Đây là lần đầu tiên các em đến Bắc Kinh à?"},{"hanzi":"是的，我们都是第一次来。","pinyin":"Shì de, wǒmen dōu shì dì-yī cì lái.","speaker":"白家月","vi":"Vâng, chúng em đều là lần đầu tiên đến ạ."},{"hanzi":"你们是来学中文的吗？","pinyin":"Nǐmen shì lái xué Zhōngwén de ma?","speaker":"王一雪","vi":"Các em đến đây để học tiếng Trung phải không?"},{"hanzi":"不是，我们是来旅游的。","pinyin":"Bú shì, wǒmen shì lái lǚyóu de.","speaker":"安妮","vi":"Không phải ạ, chúng em đến để du lịch."},{"hanzi":"我这几天都不忙，你们有事就找我。","pinyin":"Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ.","speaker":"王一雪","vi":"Mấy ngày nay chị đều không bận, các em có việc gì thì cứ tìm chị nhé."},{"hanzi":"好的，谢谢您。","pinyin":"Hǎo de, xièxie nín.","speaker":"白家月","vi":"Vâng ạ, cảm ơn chị."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi được hỏi \"你们是来学中文的吗？\" (\"Các bạn đến để học tiếng Trung à?\"), An Ni đáp \"不是，我们是来旅游的。\" (\"Không phải, chúng em đến để du lịch ạ.\"), nên mục đích đến Bắc Kinh là để du lịch.","options":["她们是来学中文的。","她们是来旅游的。","她们是来工作的。","她们是来教中文的。"],"q":"白家月和安妮这次来北京做什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我这几天都不忙，你们有事就找我。\" (\"Mấy ngày nay chị đều không bận, các em có việc gì thì cứ tìm chị.\"), nên mấy ngày tới chị ấy đều rảnh và sẵn sàng giúp đỡ.","options":["很忙，没有时间。","只有今天不忙。","这几天都不忙，她们有事可以找她。","太忙了，不能去旅游。"],"q":"王一雪这几天忙不忙？"}],"scene":"在王一雪的车里，白家月、安妮和王一雪在聊天儿。","sceneVi":"Trong xe của Vương Nhất Tuyết, Bạch Gia Nguyệt, An Ni và Vương Nhất Tuyết đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，家月，你明天有时间吗？我想请你帮个忙。","pinyin":"Wèi, Jiāyuè, nǐ míngtiān yǒu shíjiān ma? Wǒ xiǎng qǐng nǐ bāng ge máng.","speaker":"陈天中","vi":"Alo, Gia Nguyệt à, ngày mai cậu có rảnh không? Mình muốn nhờ cậu giúp một việc."},{"hanzi":"不好意思，天中，我已经到北京了。","pinyin":"Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le.","speaker":"白家月","vi":"Xin lỗi nhé Thiên Trung, mình đã đến Bắc Kinh rồi."},{"hanzi":"你是什么时候到的？","pinyin":"Nǐ shì shénme shíhou dào de?","speaker":"陈天中","vi":"Cậu đến vào lúc nào thế?"},{"hanzi":"我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。","pinyin":"Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne.","speaker":"白家月","vi":"Mình đến vào sáng nay. Cậu có việc thì có thể bảo Lý Văn giúp, cậu ấy vẫn còn ở trường đấy."},{"hanzi":"好的，那我给他打个电话。","pinyin":"Hǎo de, nà wǒ gěi tā dǎ ge diànhuà.","speaker":"陈天中","vi":"Được rồi, vậy để mình gọi điện cho cậu ấy."},{"hanzi":"好，再见！","pinyin":"Hǎo, zàijiàn!","speaker":"白家月","vi":"Ừ, tạm biệt!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我是今天早上到的。\" (\"Mình đến vào sáng nay.\"), nên Bạch Gia Nguyệt đã đến Bắc Kinh vào sáng hôm nay.","options":["昨天晚上","今天早上","今天中午","明天早上"],"q":"白家月是什么时候到北京的？"},{"answerIdx":3,"explanation":"Trong bài có câu \"你有事可以叫李文帮忙，他还在学校呢。\" (\"Cậu có việc thì có thể nhờ Lý Văn giúp, cậu ấy vẫn đang ở trường đấy.\"), nên Bạch Gia Nguyệt khuyên Trần Thiên Trung gọi cho Lý Văn.","options":["王老师","安妮","王一雪","李文"],"q":"因为自己不在学校，白家月叫陈天中找谁帮忙？"}],"scene":"在王一雪的车上，白家月接了个电话。","sceneVi":"Trên xe của Vương Nhất Tuyết, Bạch Gia Nguyệt nhận được một cuộc điện thoại."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"王老师，我们已经到北京了，是您姐姐来接的我们。","pinyin":"Wáng lǎoshī, wǒmen yǐjīng dào Běijīng le, shì nín jiějie lái jiē de wǒmen.","speaker":"Đoạn văn","vi":"Cô Vương ơi, chúng em đã đến Bắc Kinh rồi ạ, chính chị gái của cô đã đến đón chúng em."},{"hanzi":"她请我们吃了北京烤鸭，还给我们介绍了很多东西。","pinyin":"Tā qǐng wǒmen chīle Běijīng Kǎoyā, hái gěi wǒmen jièshàole hěn duō dōngxi.","speaker":"Đoạn văn","vi":"Chị ấy đã mời chúng em ăn vịt quay Bắc Kinh, còn giới thiệu cho chúng em rất nhiều thứ nữa."},{"hanzi":"我们的中文不太好，有时不太懂她的意思。","pinyin":"Wǒmen de Zhōngwén bú tài hǎo, yǒushí bú tài dǒng tā de yìsi.","speaker":"Đoạn văn","vi":"Tiếng Trung của chúng em chưa tốt lắm, đôi khi không hiểu rõ ý của chị ấy."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"是您姐姐来接的我们。她请我们吃了北京烤鸭，还给我们介绍了很多东西。\" (\"Chính chị gái cô đã đến đón chúng em. Chị ấy mời chúng em ăn vịt quay Bắc Kinh, lại còn giới thiệu cho chúng em rất nhiều thứ.\"), nên đáp án đúng là đón họ, mời ăn vịt quay Bắc Kinh và giới thiệu nhiều thứ.","options":["来接她们，请吃北京烤鸭，还介绍了很多东西。","带她们去了酒店，教她们写汉字。","请她们喝了咖啡，吃了面包和鸡蛋。","带她们坐火车去西安旅游。"],"q":"王老师的姐姐为她们做了什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们的中文不太好，有时不太懂她的意思。\" (\"Tiếng Trung của chúng em chưa tốt lắm, đôi khi không hiểu rõ ý của chị ấy.\"), nên nguyên nhân là do tiếng Trung của họ chưa tốt lắm.","options":["因为王老师的姐姐说话太快了。","因为她们刚下飞机，太累了。","因为她们的中文不太好。","因为车里声音太大，听不见。"],"q":"她们为什么有时不太懂王老师姐姐的意思？"}],"scene":"在酒店，白家月给王一飞发信息。","sceneVi":"Ở khách sạn, Bạch Gia Nguyệt nhắn tin cho Vương Nhất Phi."}],"hsk2-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，这儿有到北京大学的公交车吗？","pinyin":"Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","speaker":"白家月","vi":"Xin hỏi, ở đây có xe buýt đi đến Đại học Bắc Kinh không ạ?"},{"hanzi":"有，但车站有点儿远。","pinyin":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","speaker":"服务员","vi":"Có ạ, nhưng trạm xe hơi xa một chút."},{"hanzi":"这儿好打车吗？","pinyin":"Zhèr hǎo dǎchē ma?","speaker":"白家月","vi":"Ở đây có dễ bắt taxi không ạ?"},{"hanzi":"好打车。","pinyin":"Hǎo dǎchē.","speaker":"服务员","vi":"Dễ bắt taxi lắm ạ."},{"hanzi":"谢谢。安妮，我们还是打车去吧。","pinyin":"Xièxie. Ānnī, wǒmen háishi dǎchē qù ba.","speaker":"白家月","vi":"Cảm ơn chị. An Ni à, hay là bọn mình bắt taxi đi nhé."},{"hanzi":"好，没问题。","pinyin":"Hǎo, méi wèntí.","speaker":"安妮","vi":"Được thôi, không vấn đề gì."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, nhân viên phục vụ nói \"有，但车站有点儿远。\" (Có, nhưng trạm xe hơi xa một chút.), nên Bạch Gia Nguyệt không chọn đi xe buýt.","options":["因为这儿没有公交车","因为公交车站有点儿远","因为她不喜欢坐公交车","因为坐公交车太贵了"],"q":"为什么白家月不坐公交车去北京大学？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"安妮，我们还是打车去吧。\" (An Ni, chúng ta vẫn nên bắt taxi đi đi.) và An Ni đồng ý \"好，没问题。\" (Được, không vấn đề gì.), nên hai người quyết định bắt taxi đi.","options":["坐公交车去","走路去","打车去","开车去"],"q":"白家月和安妮最后决定怎么去北京大学？"}],"scene":"在宾馆前台，白家月和安妮向服务员咨询。","sceneVi":"Tại quầy lễ tân khách sạn, Bạch Gia Nguyệt và An Ni đang hỏi thông tin từ nhân viên."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"学校里人真多啊！","pinyin":"Xuéxiào li rén zhēn duō a!","speaker":"白家月","vi":"Trong trường đông người thật đấy!"},{"hanzi":"是啊，北京大学有四万多名学生呢！","pinyin":"Shì a, Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","speaker":"安妮","vi":"Đúng vậy, Đại học Bắc Kinh có hơn bốn mươi nghìn sinh viên cơ mà!"},{"hanzi":"你是怎么知道的？","pinyin":"Nǐ shì zěnme zhīdào de?","speaker":"白家月","vi":"Sao cậu lại biết thế?"},{"hanzi":"是网上说的，网上还说北京大学有三千多名外国学生。","pinyin":"Shì wǎngshang shuō de, wǎngshang hái shuō Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuéshēng.","speaker":"安妮","vi":"Là trên mạng nói đấy, trên mạng còn nói Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài nữa."},{"hanzi":"我也想来这儿学习。","pinyin":"Wǒ yě xiǎng lái zhèr xuéxí.","speaker":"白家月","vi":"Mình cũng muốn đến đây học tập."},{"hanzi":"那边就有一间教室，我们去看一下吧。","pinyin":"Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba.","speaker":"安妮","vi":"Đằng kia có ngay một phòng học đấy, chúng mình qua xem thử một chút đi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, An Ni nói \"网上还说北京大学有三千多名外国学生。\" (Trên mạng còn nói Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài.), nên đáp án đúng là hơn ba nghìn sinh viên.","options":["四万多名","四千多名","三千多名","三万多名"],"q":"安妮在网上看到，北京大学有多少名外国学生？"},{"answerIdx":0,"explanation":"Trong bài, An Ni nói \"那边就有一间教室，我们去看一下吧。\" (Đằng kia có một phòng học, chúng ta qua xem một chút đi.), nên cô ấy rủ Bạch Gia Nguyệt đi xem phòng học.","options":["去那边的教室看一下","去网上查一下学校","去认识外国学生","去学校外面逛一逛"],"q":"说完以后，安妮想和白家月一起去做什么？"}],"scene":"在北京大学，白家月和安妮在参观校园。","sceneVi":"Tại Đại học Bắc Kinh, Bạch Gia Nguyệt và An Ni đang tham quan khuôn viên trường."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"家月，你看，学校里有家电影院！","pinyin":"Jiāyuè, nǐ kàn, xuéxiào li yǒu jiā diànyǐngyuàn!","speaker":"安妮","vi":"Gia Nguyệt, cậu nhìn kìa, trong trường có một rạp chiếu phim đấy!"},{"hanzi":"是啊，电影院还不小。","pinyin":"Shì a, diànyǐngyuàn hái bù xiǎo.","speaker":"白家月","vi":"Đúng vậy, rạp chiếu phim cũng không nhỏ đâu."},{"hanzi":"他们卖的电影票也很便宜。","pinyin":"Tāmen mài de diànyǐngpiào yě hěn piányi.","speaker":"安妮","vi":"Vé xem phim họ bán cũng rất rẻ."},{"hanzi":"天啊！有的还不到二十块钱。","pinyin":"Tiān a! Yǒude hái bú dào èrshí kuài qián.","speaker":"白家月","vi":"Trời ơi! Có vé còn chưa đến hai mươi tệ nữa."},{"hanzi":"那你想不想去看个电影？","pinyin":"Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?","speaker":"安妮","vi":"Thế cậu có muốn đi xem một bộ phim không?"},{"hanzi":"还是别看电影了，北京大学就很好看！","pinyin":"Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!","speaker":"白家月","vi":"Thôi đừng xem phim nữa, bản thân Đại học Bắc Kinh đã rất đẹp rồi!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, An Ni nói \"他们卖的电影票也很便宜。\" (Vé xem phim họ bán cũng rất rẻ.) và Bạch Gia Nguyệt nói thêm \"有的还不到二十块钱。\" (Có vé còn chưa tới hai mươi tệ.), nên giá vé rất rẻ.","options":["很贵，要二十多块钱","很便宜，有的不到二十块钱","不卖给外国学生","今天已经卖完了"],"q":"北京大学电影院的电影票怎么样？"},{"answerIdx":3,"explanation":"Trong bài, Bạch Gia Nguyệt từ chối \"还是别看电影了，北京大学就很好看！\" (Thôi đừng xem phim nữa, Đại học Bắc Kinh đã rất đẹp rồi!), vì cô thấy khuôn viên trường đã rất đẹp.","options":["因为电影票太贵了","因为电影院太小了","因为她不喜欢看电影","因为她觉得北京大学就很好看"],"q":"白家月为什么说现在不看电影了？"}],"scene":"在北京大学，白家月和安妮在参观校园。","sceneVi":"Tại Đại học Bắc Kinh, Bạch Gia Nguyệt và An Ni đang tham quan khuôn viên trường."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"北京大学很大，有四万多名学生。","pinyin":"Běijīng Dàxué hěn dà, yǒu sìwàn duō míng xuéshēng.","speaker":"Đoạn văn","vi":"Đại học Bắc Kinh rất rộng lớn, có hơn bốn mươi nghìn sinh viên."},{"hanzi":"学校很漂亮，里边还有家电影院，电影票也不贵，我们有时间还想再过来看个电影。","pinyin":"Xuéxiào hěn piàoliang, lǐbian hái yǒu jiā diànyǐngyuàn, diànyǐngpiào yě bú guì, wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng.","speaker":"Đoạn văn","vi":"Ngôi trường rất đẹp, bên trong còn có một rạp chiếu phim, vé xem phim cũng không đắt, lúc nào có thời gian chúng mình còn muốn quay lại đây xem một bộ phim nữa."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong tin nhắn gửi Trần Thiên Trung, Bạch Gia Nguyệt viết \"北京大学很大，有四万多名学生。学校很漂亮...\" (Đại học Bắc Kinh rất lớn, có hơn bốn vạn sinh viên. Trường rất đẹp...).","options":["很大，也很漂亮","人很少，很安静","不大，没有电影院","电影票非常贵"],"q":"在信息里，白家月觉得北京大学怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们有时间还想再过来看个电影。\" (Khi nào có thời gian chúng mình còn muốn quay lại đây xem một bộ phim.), nên họ muốn quay lại xem phim.","options":["找朋友吃饭","来这里上课","再过来看个电影","参观一下教室"],"q":"如果以后有时间，她们还想再来北京大学做什么？"}],"scene":"在北京大学门口，白家月给陈天中发信息。","sceneVi":"Ở cổng Đại học Bắc Kinh, Bạch Gia Nguyệt nhắn tin cho Trần Thiên Trung."}],"hsk2-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天回来这么晚啊！","pinyin":"Jīntiān huílái zhème wǎn a!","speaker":"王一雪","vi":"Hôm nay anh về muộn thế!"},{"hanzi":"工作太多了，下班的时候没做完。","pinyin":"Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán.","speaker":"刘明","vi":"Công việc nhiều quá, lúc tan làm vẫn chưa làm xong."},{"hanzi":"菜都做好了，过来吃饭吧。","pinyin":"Cài dōu zuòhǎo le, guòlái chī fàn ba.","speaker":"王一雪","vi":"Cơm canh đều nấu xong rồi, lại đây ăn cơm đi."},{"hanzi":"我想休息一下，喝杯水。","pinyin":"Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ.","speaker":"刘明","vi":"Anh muốn nghỉ ngơi một chút, uống cốc nước đã."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"王一雪","vi":"Vâng ạ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh giải thích với vợ \"工作太多了，下班的时候没做完。\" (Công việc nhiều quá, lúc tan làm vẫn chưa làm xong.), nên anh về muộn.","options":["因为他去外面吃饭了","因为工作太多，下班时没做完","因为路上的车太多了","因为他去买东西了"],"q":"刘明今天为什么这么晚才回家？"},{"answerIdx":1,"explanation":"Trong bài, khi Vương Nhất Tuyết mời ăn cơm, Lưu Minh trả lời \"我想休息一下，喝杯水。\" (Anh muốn nghỉ ngơi một chút, uống một cốc nước.).","options":["马上过来吃饭","先休息一下，喝杯水","再做一点儿工作","去帮王一雪做菜"],"q":"刘明回到家后，现在最想做什么？"}],"scene":"在家门口，刘明开门进到家里。","sceneVi":"Ở cửa nhà, Lưu Minh mở cửa bước vào nhà."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我们找个时间去旅游，怎么样？","pinyin":"Wǒmen zhǎo gè shíjiān qù lǚyóu, zěnmeyàng?","speaker":"刘明","vi":"Chúng mình tìm thời gian đi du lịch, thế nào?"},{"hanzi":"好啊，我也很想一起出去玩。","pinyin":"Hǎo a, wǒ yě hěn xiǎng yìqǐ chūqù wán.","speaker":"王一雪","vi":"Hay quá, em cũng rất muốn cùng nhau ra ngoài chơi."},{"hanzi":"你想去哪儿？","pinyin":"Nǐ xiǎng qù nǎr?","speaker":"刘明","vi":"Em muốn đi đâu?"},{"hanzi":"我还没想好呢。","pinyin":"Wǒ hái méi xiǎnghǎo ne.","speaker":"王一雪","vi":"Em vẫn chưa nghĩ ra nữa."},{"hanzi":"那你再想一想，你想好了，我来买票。","pinyin":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.","speaker":"刘明","vi":"Vậy em nghĩ thêm chút đi, khi nào em nghĩ xong thì anh sẽ mua vé."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lưu Minh rủ Vương Nhất Tuyết \"我们找个时间去旅游，怎么样？\" (Chúng ta tìm thời gian đi du lịch nhé, thế nào?).","options":["去看电影","去买东西","去旅游","去朋友家玩"],"q":"刘明想和王一雪找时间去做什么？"},{"answerIdx":0,"explanation":"Trong bài, Lưu Minh nói \"那你再想一想，你想好了，我来买票。\" (Vậy em nghĩ thêm đi, khi nào em nghĩ xong thì anh sẽ mua vé.).","options":["他来买票","他先去休息","他去问朋友","他再去想一想"],"q":"王一雪想好去哪儿以后，刘明打算做什么？"}],"scene":"在客厅，刘明和王一雪在聊天儿。","sceneVi":"Ở phòng khách, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"吃个苹果吧，我都洗好了。","pinyin":"Chī gè píngguǒ ba, wǒ dōu xǐhǎo le.","speaker":"刘明","vi":"Ăn quả táo đi, anh rửa sạch cả rồi."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"王一雪","vi":"Vâng ạ."},{"hanzi":"就在桌子上，你自己拿。","pinyin":"Jiù zài zhuōzi shang, nǐ zìjǐ ná.","speaker":"刘明","vi":"Ở ngay trên bàn đấy, em tự lấy nhé."},{"hanzi":"我去洗洗手。对了，我们去西安旅游，怎么样？","pinyin":"Wǒ qù xǐxi shǒu. Duìle, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?","speaker":"王一雪","vi":"Em đi rửa tay đã. À đúng rồi, chúng mình đi Tây An du lịch, thế nào?"},{"hanzi":"为什么想去西安？","pinyin":"Wèi shénme xiǎng qù Xī'ān?","speaker":"刘明","vi":"Sao em lại muốn đi Tây An?"},{"hanzi":"我看了看网上的介绍，这个时候去西安很不错！","pinyin":"Wǒ kànle kàn wǎngshang de jièshào, zhège shíhou qù Xī'ān hěn búcuò!","speaker":"王一雪","vi":"Em có xem qua giới thiệu trên mạng rồi, thời điểm này đi Tây An rất tuyệt đấy!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Lưu Minh bảo tự lấy táo trên bàn ăn, Vương Nhất Tuyết nói \"我去洗洗手。\" (Em đi rửa tay đã.).","options":["去洗苹果","去洗洗手","去拿桌子上的水","去网上找介绍"],"q":"吃苹果以前，王一雪先去做什么？"},{"answerIdx":3,"explanation":"Trong bài, Vương Nhất Tuyết giải thích \"我看了看网上的介绍，这个时候去西安很不错！\" (Em xem qua giới thiệu trên mạng rồi, tầm này đi Tây An rất tuyệt!).","options":["因为刘明去过西安","因为西安的苹果很好吃","因为她有朋友在西安","因为她看了网上的介绍，觉得这个时候去很不错"],"q":"王一雪为什么想去西安旅游？"}],"scene":"在客厅，刘明和王一雪在聊天儿。","sceneVi":"Ở phòng khách, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"早上，刘明开车送孩子去学校，送完孩子回家后，医院就来电话了，让他回去上班。","pinyin":"Zǎoshang, Liú Míng kāichē sòng háizi qù xuéxiào, sòngwán háizi huí jiā hòu, yīyuàn jiù lái diànhuà le, ràng tā huíqù shàngbān.","speaker":"Đoạn văn","vi":"Buổi sáng, Lưu Minh lái xe đưa con đi học, đưa con xong về đến nhà thì bệnh viện gọi điện tới, bảo anh ấy quay lại đi làm."},{"hanzi":"我觉得他这个月每天都很累，真想让他休息休息。","pinyin":"Wǒ juéde tā zhège yuè měi tiān dōu hěn lèi, zhēn xiǎng ràng tā xiūxi xiūxi.","speaker":"Đoạn văn","vi":"Mình thấy tháng này ngày nào anh ấy cũng rất mệt, thật sự muốn để anh ấy nghỉ ngơi một chút."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"送完孩子回家后，医院就来电话了，让他回去上班。\" (Sau khi đưa con đi học về nhà thì bệnh viện gọi điện đến, bảo anh ấy quay lại làm việc.).","options":["他在家里休息了一天","医院来电话让他回去上班","他和王一雪一起去旅游了","他又开车去买东西了"],"q":"刘明送完孩子回家以后，发生了什么事？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我觉得他这个月每天都很累，真想让他休息休息。\" (Mình thấy tháng này ngày nào anh ấy cũng rất mệt, thật muốn để anh ấy nghỉ ngơi.).","options":["每天都很开心","有很多时间休息","每天都很累","工作很少，不太忙"],"q":"王一雪觉得刘明这个月怎么样？"}],"scene":"在家里，王一雪给好朋友打电话。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang gọi điện thoại cho bạn thân."}],"hsk2-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"妈妈，我们来过这家商场吗？","pinyin":"Māma, wǒmen láiguo zhè jiā shāngchǎng ma?","speaker":"刘小雪","vi":"Mẹ ơi, chúng ta từng đến trung tâm thương mại này chưa?"},{"hanzi":"没来过，这是新开的。","pinyin":"Méi láiguo, zhè shì xīn kāi de.","speaker":"王一雪","vi":"Chưa từng đến, đây là chỗ mới mở đấy."},{"hanzi":"我们进去看看吧。","pinyin":"Wǒmen jìnqù kànkan ba.","speaker":"刘小雪","vi":"Chúng ta vào trong xem thử đi."},{"hanzi":"好啊！你想买点儿什么？","pinyin":"Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?","speaker":"王一雪","vi":"Được thôi! Con muốn mua chút gì?"},{"hanzi":"我想买条裤子。","pinyin":"Wǒ xiǎng mǎi tiáo kùzi.","speaker":"刘小雪","vi":"Con muốn mua một chiếc quần."},{"hanzi":"没问题。","pinyin":"Méi wèntí.","speaker":"王一雪","vi":"Không thành vấn đề."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Lưu Tiểu Tuyết hỏi đã từng đến trung tâm thương mại này chưa, Vương Nhất Tuyết trả lời \"没来过，这是新开的。\" (Chưa từng đến, đây là chỗ mới mở.).","options":["她们以前来过很多次","她们没来过，因为这是新开的","这家商场今天没开门","这家商场只卖书包"],"q":"关于这家商场，下面哪句话是对的？"},{"answerIdx":0,"explanation":"Trong bài, khi mẹ hỏi muốn mua gì, Lưu Tiểu Tuyết trả lời \"我想买条裤子。\" (Con muốn mua một chiếc quần.).","options":["一条裤子","一件白色的衣服","一个新书包","一些水果"],"q":"刘小雪进商场想买什么？"}],"scene":"在商场门口，王一雪和刘小雪在聊天儿。","sceneVi":"Ở cổng trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"妈妈，我想买这条白色的裤子。","pinyin":"Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi.","speaker":"刘小雪","vi":"Mẹ ơi, con muốn mua chiếc quần màu trắng này."},{"hanzi":"你有很多白色的衣服，为什么还买白色的？","pinyin":"Nǐ yǒu hěn duō báisè de yīfu, wèi shénme hái mǎi báisè de?","speaker":"王一雪","vi":"Con có rất nhiều quần áo màu trắng rồi, sao còn mua màu trắng nữa?"},{"hanzi":"因为我喜欢白色啊！","pinyin":"Yīnwèi wǒ xǐhuan báisè a!","speaker":"刘小雪","vi":"Vì con thích màu trắng mà!"},{"hanzi":"我觉得这条白色的不太好看，你试试那条红色的吧。","pinyin":"Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba.","speaker":"王一雪","vi":"Mẹ thấy chiếc màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem."},{"hanzi":"我没穿过红色的，红色的好看吗？","pinyin":"Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?","speaker":"刘小雪","vi":"Con chưa từng mặc đồ màu đỏ, màu đỏ có đẹp không ạ?"},{"hanzi":"就是因为没穿过，所以要试试啊！","pinyin":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","speaker":"王一雪","vi":"Chính vì chưa từng mặc nên mới phải thử đấy!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Tiểu Tuyết nói \"妈妈，我想买这条白色的裤子。\" (Mẹ ơi, con muốn mua chiếc quần màu trắng này.) và giải thích \"因为我喜欢白色啊！\" (Vì con thích màu trắng mà!).","options":["红色的，因为她有很多白色的衣服","白色的，因为她喜欢白色","红色的，因为她没穿过红色的","白色的，因为红色的不好看"],"q":"刘小雪本来想买什么颜色的裤子？为什么？"},{"answerIdx":2,"explanation":"Trong bài, mẹ nói \"我觉得这条白色的不太好看，你试试那条红色的吧。\" (Mẹ thấy chiếc màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem.) và nói thêm \"就是因为没穿过，所以要试试啊！\" (Chính vì chưa từng mặc nên mới phải thử đấy!).","options":["因为那条白色的卖完了","因为那条红色的更便宜","因为妈妈觉得白色的不太好看，而且小雪没穿过红色的","因为小雪有很多红色的衣服"],"q":"妈妈为什么让刘小雪试试那条红色的裤子？"}],"scene":"在商场，王一雪和刘小雪在看衣服。","sceneVi":"Trong trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang xem quần áo."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"妈妈，我想买个新书包。","pinyin":"Māma, wǒ xiǎng mǎi gè xīn shūbāo.","speaker":"刘小雪","vi":"Mẹ ơi, con muốn mua một chiếc cặp sách mới."},{"hanzi":"好，那边卖书包，我们过去看看吧。","pinyin":"Hǎo, nàbiān mài shūbāo, wǒmen guòqù kànkan ba.","speaker":"王一雪","vi":"Được, bên kia có bán cặp sách, chúng ta qua xem thử đi."},{"hanzi":"这么多漂亮的书包！","pinyin":"Zhème duō piàoliang de shūbāo!","speaker":"刘小雪","vi":"Nhiều cặp sách đẹp quá đi!"},{"hanzi":"红色的、绿色的、黑色的，你想买哪个？","pinyin":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","speaker":"王一雪","vi":"Cái màu đỏ, màu xanh lá, màu đen, con muốn mua cái nào?"},{"hanzi":"绿色的吧。","pinyin":"Lǜsè de ba.","speaker":"刘小雪","vi":"Cái màu xanh lá đi ạ."},{"hanzi":"不错，我也觉得绿色的更好看。","pinyin":"Búcuò, wǒ yě juéde lǜsè de gèng hǎokàn.","speaker":"王一雪","vi":"Ổn đấy, mẹ cũng thấy cái màu xanh lá đẹp hơn."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài, khi mẹ hỏi muốn mua chiếc cặp sách màu đỏ, xanh lá hay đen, Lưu Tiểu Tuyết chọn \"绿色的吧。\" (Chiếc màu xanh lá đi ạ.).","options":["白色的","红色的","黑色的","绿色的"],"q":"刘小雪最后想买什么颜色的书包？"},{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết đồng tình với lựa chọn của con \"不错，我也觉得绿色的更好看。\" (Được đấy, mẹ cũng thấy màu xanh lá đẹp hơn.).","options":["她也觉得绿色的更好看","她觉得黑色的更好看","她觉得绿色的不太好看","她觉得那里的书包都不漂亮"],"q":"王一雪对刘小雪选的书包怎么看？"}],"scene":"在商场，王一雪和刘小雪在看书包。","sceneVi":"Trong trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang xem cặp sách."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我和妈妈去了一家商场。","pinyin":"Wǒ hé māma qùle yì jiā shāngchǎng.","speaker":"Đoạn văn","vi":"Mình và mẹ đã đi đến một trung tâm thương mại."},{"hanzi":"因为是新开的，所以这几天东西很便宜。","pinyin":"Yīnwèi shì xīn kāi de, suǒyǐ zhè jǐ tiān dōngxi hěn piányi.","speaker":"Đoạn văn","vi":"Vì mới khai trương nên mấy hôm nay đồ đạc rất rẻ."},{"hanzi":"商场里的衣服颜色很多。","pinyin":"Shāngchǎng li de yīfu yánsè hěn duō.","speaker":"Đoạn văn","vi":"Quần áo trong trung tâm thương mại có rất nhiều màu sắc."},{"hanzi":"我没穿过红色的裤子，妈妈让我试了试，我觉得我穿红色的也很好看。","pinyin":"Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn.","speaker":"Đoạn văn","vi":"Mình chưa từng mặc quần màu đỏ, mẹ bảo mình thử xem sao, mình thấy mình mặc màu đỏ cũng rất đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong nhật ký, Lưu Tiểu Tuyết viết \"因为是新开的，所以这几天东西很便宜。\" (Vì mới khai trương nên mấy hôm nay đồ đạc rất rẻ.).","options":["因为里面的衣服很少","因为那家商场是新开的","因为那里的衣服不好看","因为商场很大"],"q":"为什么这几天那家商场里的东西很便宜？"},{"answerIdx":2,"explanation":"Trong bài có câu \"妈妈让我试了试，我觉得我穿红色的也很好看。\" (Mẹ bảo mình thử một chút, mình thấy mình mặc màu đỏ cũng rất đẹp.).","options":["她觉得自己穿白色的更好看","她觉得自己穿红色的不太好看","她觉得自己穿红色的也很好看","她不想试红色的裤子"],"q":"试了红色的裤子以后，刘小雪觉得怎么样？"}],"scene":"在房间，刘小雪在写日记。","sceneVi":"Trong phòng, Lưu Tiểu Tuyết đang viết nhật ký."}],"hsk2-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，快下来吧，第一次去中国朋友家，别晚了。","pinyin":"Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le.","speaker":"安妮","vi":"Gia Nguyệt, mau xuống đi, lần đầu tiên đến nhà bạn người Trung Quốc, đừng đến muộn đấy."},{"hanzi":"还有时间，你上来吧。","pinyin":"Hái yǒu shíjiān, nǐ shànglái ba.","speaker":"白家月","vi":"Vẫn còn thời gian mà, cậu lên đây đi."},{"hanzi":"我不上去了，就在下面等你。","pinyin":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","speaker":"安妮","vi":"Mình không lên nữa đâu, cứ ở dưới này đợi cậu."},{"hanzi":"那我一会儿就下去。","pinyin":"Nà wǒ yíhuìr jiù xiàqù.","speaker":"白家月","vi":"Vậy một lát nữa mình xuống ngay."},{"hanzi":"你快点儿吧。","pinyin":"Nǐ kuài diǎnr ba.","speaker":"安妮","vi":"Cậu nhanh lên một chút đi."},{"hanzi":"没事，一雪姐说11点前到就可以。","pinyin":"Méishì, Yīxuě jiě shuō shíyī diǎn qián dào jiù kěyǐ.","speaker":"白家月","vi":"Không sao đâu, chị Nhất Tuyết nói đến trước 11 giờ là được rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bối cảnh có ghi \"在宾馆楼下，安妮给白家月打电话。\" (Ở dưới tầng khách sạn, An Ni gọi điện cho Bạch Gia Nguyệt.) và An Ni nói \"我不上去了，就在下面等你。\" (Mình không lên đâu, đợi cậu ở dưới thôi.).","options":["在白家月的房间里","在宾馆楼下","在王一雪家门口","在公交车站"],"q":"打电话的时候，安妮在哪里等白家月？"},{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"没事，一雪姐说11点前到就可以。\" (Không sao, chị Nhất Tuyết nói đến trước 11 giờ là được.).","options":["十一点以后","十一点前","十二点前","下午一点"],"q":"一雪姐让她们什么时候到她家？"}],"scene":"在宾馆楼下，安妮给白家月打电话。","sceneVi":"Ở dưới lầu khách sạn, An Ni gọi điện thoại cho Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。","pinyin":"Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai.","speaker":"王一雪","vi":"Gia Nguyệt, An Ni, mau vào đi! Để chị giới thiệu với hai em, đây là ông nội, bà nội của các cháu."},{"hanzi":"你们好！","pinyin":"Nǐmen hǎo!","speaker":"白家月、安妮","vi":"Cháu chào ông bà ạ!"},{"hanzi":"爸，妈，这是白家月，这是安妮。她们都是一飞的学生。","pinyin":"Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuésheng.","speaker":"王一雪","vi":"Bố, mẹ, đây là Bạch Gia Nguyệt, đây là An Ni. Hai bạn ấy đều là học sinh của Nhất Phi."},{"hanzi":"家月、安妮，你们好！","pinyin":"Jiāyuè, Ānnī, nǐmen hǎo!","speaker":"刘爷爷","vi":"Chào Gia Nguyệt, An Ni!"},{"hanzi":"这是送你们的礼物。","pinyin":"Zhè shì sòng nǐmen de lǐwù.","speaker":"白家月","vi":"Đây là quà tặng ông bà ạ."},{"hanzi":"你们太客气了，还拿这么多礼物来！","pinyin":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","speaker":"刘爷爷","vi":"Các cháu khách sáo quá, còn mang nhiều quà đến thế này!"},{"hanzi":"一雪姐，这是给孩子们准备的礼物。","pinyin":"Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù.","speaker":"白家月","vi":"Chị Nhất Tuyết, đây là quà bọn em chuẩn bị cho các cháu."},{"hanzi":"谢谢！你们别客气，快坐吧！","pinyin":"Xièxie! Nǐmen bié kèqi, kuài zuò ba!","speaker":"王一雪","vi":"Cảm ơn hai em! Đừng khách sáo, mau ngồi đi!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết giới thiệu với bố mẹ \"她们都是一飞的学生。\" (Hai bạn ấy đều là học sinh của Nhất Phi.).","options":["王一雪的学生","刘爷爷的学生","一飞的学生","孩子们的老师"],"q":"白家月和安妮是谁的学生？"},{"answerIdx":2,"explanation":"Trong bài, sau khi tặng quà cho ông bà, Bạch Gia Nguyệt nói tiếp \"一雪姐，这是给孩子们准备的礼物。\" (Chị Nhất Tuyết ơi, đây là quà chuẩn bị cho các cháu ạ.).","options":["给一飞的","给安妮的","给孩子们的","给朋友们的"],"q":"除了送给爷爷、奶奶的礼物以外，白家月还给谁准备了礼物？"}],"scene":"在王一雪家，白家月和安妮来做客。","sceneVi":"Ở nhà Vương Nhất Tuyết, Bạch Gia Nguyệt và An Ni đến chơi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"都12点了，我们吃饭吧。","pinyin":"Dōu shí'èr diǎn le, wǒmen chī fàn ba.","speaker":"王一雪","vi":"Đã 12 giờ rồi, chúng ta ăn cơm thôi."},{"hanzi":"这么多好吃的，您太客气了！","pinyin":"Zhème duō hǎochī de, nín tài kèqi le!","speaker":"白家月","vi":"Nhiều món ngon quá, chị khách sáo quá rồi!"},{"hanzi":"都是我自己做的，你们多吃点儿。","pinyin":"Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr.","speaker":"王一雪","vi":"Đều là tự tay chị nấu cả đấy, hai em ăn nhiều vào nhé."},{"hanzi":"奶茶也很好喝，是您自己做的吗？","pinyin":"Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?","speaker":"白家月","vi":"Trà sữa cũng rất ngon, có phải do chị tự làm không ạ?"},{"hanzi":"不是，奶茶是爷爷买的。","pinyin":"Bú shì, nǎichá shì yéye mǎi de.","speaker":"王一雪","vi":"Không phải, trà sữa là ông nội mua đấy."},{"hanzi":"在哪儿买的？我还没喝过这么好喝的奶茶。","pinyin":"Zài nǎr mǎi de? Wǒ hái méi hēguo zhème hǎohē de nǎichá.","speaker":"白家月","vi":"Mua ở đâu thế ạ? Em chưa từng uống trà sữa nào ngon như vậy."},{"hanzi":"就在前边的商场，吃完饭你们可以跟我去看看。","pinyin":"Jiù zài qiánbiān de shāngchǎng, chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan.","speaker":"王一雪","vi":"Ngay ở trung tâm thương mại phía trước, ăn cơm xong hai em có thể đi cùng chị qua xem thử."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Bạch Gia Nguyệt hỏi trà sữa có phải do chị tự làm không, Vương Nhất Tuyết đáp \"不是，奶茶是爷爷买的。\" (Không phải, trà sữa là do ông nội mua đấy.).","options":["王一雪自己做的","爷爷买的","安妮买的","孩子们买的"],"q":"白家月喝的奶茶是谁买的？"},{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"就在前边的商场，吃完饭你们可以跟我去看看。\" (Ở ngay trung tâm thương mại phía trước, ăn cơm xong các em có thể đi cùng chị qua đó xem.).","options":["在家多喝点儿奶茶","跟她去前边的商场看看","回宾馆休息一下","学怎么做奶茶"],"q":"吃完饭以后，王一雪建议她们去做什么？"}],"scene":"在王一雪家，白家月和安妮在吃饭。","sceneVi":"Ở nhà Vương Nhất Tuyết, Bạch Gia Nguyệt và An Ni đang ăn cơm."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"回国前一天，我们去一雪姐家了。","pinyin":"Huí guó qián yì tiān, wǒmen qù Yīxuě jiě jiā le.","speaker":"Đoạn văn","vi":"Một ngày trước khi về nước, chúng tôi đã đến nhà chị Nhất Tuyết."},{"hanzi":"到她家的时候，饭菜都做好了。","pinyin":"Dào tā jiā de shíhou, fàncài dōu zuòhǎo le.","speaker":"Đoạn văn","vi":"Khi đến nhà chị ấy, cơm nước đều đã nấu xong cả rồi."},{"hanzi":"刘爷爷还准备了奶茶。","pinyin":"Liú yéye hái zhǔnbèile nǎichá.","speaker":"Đoạn văn","vi":"Ông nội Lưu còn chuẩn bị cả trà sữa nữa."},{"hanzi":"因为吃了太多东西，我们吃完饭是走回酒店的。","pinyin":"Yīnwèi chīle tài duō dōngxi, wǒmen chīwán fàn shì zǒuhuí jiǔdiàn de.","speaker":"Đoạn văn","vi":"Vì ăn quá nhiều đồ ăn nên ăn cơm xong chúng tôi đã đi bộ về khách sạn."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong tin nhắn, Bạch Gia Nguyệt viết \"回国前一天，我们去一雪姐家了。\" (Một ngày trước khi về nước, chúng mình đã đến nhà chị Nhất Tuyết.).","options":["回国前一天","刚到中国的那一天","回国以后","去商场买东西以后"],"q":"她们是什么时候去一雪姐家的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"因为吃了太多东西，我们吃完饭是走回酒店的。\" (Vì ăn quá nhiều đồ nên sau khi ăn xong chúng mình đã đi bộ về khách sạn.).","options":["因为酒店离一雪姐家很远","因为那边不好打车","因为她们吃了太多东西","因为她们想去商场看衣服"],"q":"吃完饭以后，她们为什么走回酒店？"}],"scene":"在宾馆，白家月给李文发信息。","sceneVi":"Ở khách sạn, Bạch Gia Nguyệt nhắn tin cho Lý Văn."}],"hsk2-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"明天就是女儿的生日了。","pinyin":"Míngtiān jiù shì nǚ'ér de shēngrì le.","speaker":"王一雪","vi":"Ngày mai là sinh nhật của con gái rồi đấy."},{"hanzi":"你不说，我还真忘了。我们给她准备个什么礼物呢？","pinyin":"Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi gè shénme lǐwù ne?","speaker":"刘明","vi":"Em không nhắc là anh quên thật đấy. Chúng ta chuẩn bị món quà gì cho con bé đây?"},{"hanzi":"她喜欢画画，你觉得画笔怎么样？","pinyin":"Tā xǐhuan huà huà, nǐ juéde huàbǐ zěnmeyàng?","speaker":"王一雪","vi":"Con bé thích vẽ tranh, anh thấy bút vẽ thì thế nào?"},{"hanzi":"就送画笔吧！","pinyin":"Jiù sòng huàbǐ ba!","speaker":"刘明","vi":"Vậy tặng bút vẽ đi!"},{"hanzi":"那我明天上午就去买。","pinyin":"Nà wǒ míngtiān shàngwǔ jiù qù mǎi.","speaker":"王一雪","vi":"Vậy sáng mai em đi mua luôn."},{"hanzi":"好的！我再给她买个大大的生日蛋糕。","pinyin":"Hǎo de! Wǒ zài gěi tā mǎi gè dàdà de shēngrì dàngāo.","speaker":"刘明","vi":"Được! Anh sẽ mua thêm cho con bé một chiếc bánh sinh nhật thật to."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"她喜欢画画，你觉得画笔怎么样？\" (Con bé thích vẽ tranh, anh thấy bút vẽ thế nào?) và \"就送画笔吧！\" (Vậy tặng bút vẽ đi!), nên đáp án đúng là 画笔 (bút vẽ).","options":["一本新书","画笔","一件白色的衣服","黑色的狗"],"q":"他们决定给女儿买什么生日礼物？"},{"answerIdx":0,"explanation":"Trong bài, Lưu Minh nói: \"我再给她买个大大的生日蛋糕。\" (Anh sẽ mua thêm cho con bé một chiếc bánh sinh nhật thật to.), nên đáp án đúng là 一个大大的生日蛋糕 (một chiếc bánh sinh nhật thật to).","options":["一个大大的生日蛋糕","一些长长的面条儿","一只白色的小猫","一张电影票"],"q":"除了礼物以外，刘明还要给女儿买什么？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"小雪，生日快乐！","pinyin":"Xiǎoxuě, shēngrì kuàilè!","speaker":"刘明","vi":"Tiểu Tuyết, chúc mừng sinh nhật con!"},{"hanzi":"姐姐，生日快乐！","pinyin":"Jiějie, shēngrì kuàilè!","speaker":"刘小明","vi":"Chị ơi, chúc mừng sinh nhật chị!"},{"hanzi":"小雪，这是爸爸、妈妈送你的礼物。","pinyin":"Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù.","speaker":"王一雪","vi":"Tiểu Tuyết, đây là món quà bố mẹ tặng cho con."},{"hanzi":"你打开看看喜欢不喜欢。","pinyin":"Nǐ dǎkāi kànkan xǐhuan bu xǐhuan.","speaker":"刘明","vi":"Con mở ra xem có thích không."},{"hanzi":"画笔！我很喜欢！","pinyin":"Huàbǐ! Wǒ hěn xǐhuan!","speaker":"刘小雪","vi":"Bút vẽ! Con thích lắm ạ!"},{"hanzi":"那你想画点儿什么？","pinyin":"Nà nǐ xiǎng huà diǎnr shénme?","speaker":"王一雪","vi":"Thế con muốn vẽ gì nào?"},{"hanzi":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","pinyin":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","speaker":"刘小雪","vi":"Vẽ gia đình mình ạ! Có bố, mẹ, em trai, còn có chú chó màu đen, chú mèo màu trắng nữa..."},{"hanzi":"那我要画一个穿白色衣服的姐姐。","pinyin":"Nà wǒ yào huà yí gè chuān báisè yīfu de jiějie.","speaker":"刘小明","vi":"Vậy em sẽ vẽ một người chị mặc áo màu trắng."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, khi được hỏi muốn vẽ gì, Lưu Tiểu Tuyết trả lời: \"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。\" (Vẽ gia đình chúng ta! Có bố, mẹ, em trai, còn có chó đen, mèo trắng nữa.), nên đáp án đúng là 画他们的家 (vẽ gia đình của họ).","options":["画学校和同学","画穿白色衣服的姐姐","画他们的家","画生日蛋糕和面条儿"],"q":"收到画笔后，刘小雪想画什么？"},{"answerIdx":3,"explanation":"Trong bài, em trai Lưu Tiểu Minh nói: \"那我要画一个穿白色衣服的姐姐。\" (Vậy em muốn vẽ một người chị mặc áo trắng.), nên đáp án đúng là 画穿白色衣服的姐姐 (vẽ người chị mặc áo trắng).","options":["画一条黑色的狗","画一只白色的猫","画爸爸和妈妈","画穿白色衣服的姐姐"],"q":"弟弟刘小明想画什么？"}],"scene":"在客厅，刘明一家人在聊天儿。","sceneVi":"Ở phòng khách, gia đình Lưu Minh đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"小雪，看看今天有什么好吃的。","pinyin":"Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de.","speaker":"刘明","vi":"Tiểu Tuyết, xem hôm nay có những món gì ngon nào."},{"hanzi":"长长的面条儿，大大的蛋糕。","pinyin":"Chángcháng de miàntiáor, dàdà de dàngāo.","speaker":"刘小雪","vi":"Mì sợi dài thật dài, bánh kem to thật to ạ."},{"hanzi":"你看，还有鱼啊肉啊什么的，都是你喜欢吃的。","pinyin":"Nǐ kàn, hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de.","speaker":"刘明","vi":"Con xem, còn có cá, thịt các thứ nữa, đều là những món con thích ăn đấy."},{"hanzi":"谢谢爸爸、妈妈！","pinyin":"Xièxie bàba, māma!","speaker":"刘小雪","vi":"Con cảm ơn bố mẹ ạ!"},{"hanzi":"快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","pinyin":"Kuài qù jiào dìdi guòlái chī fàn ba, chīwán fàn wǒmen hái yào chūqù wán ne.","speaker":"王一雪","vi":"Mau đi gọi em trai qua ăn cơm đi con, ăn xong chúng ta còn đi ra ngoài chơi nữa đấy."},{"hanzi":"过生日真好啊！","pinyin":"Guò shēngrì zhēn hǎo a!","speaker":"刘小雪","vi":"Đón sinh nhật thật là thích quá đi!"},{"hanzi":"是的，过生日就要吃好吃的，还要高高兴兴地玩。","pinyin":"Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","speaker":"王一雪","vi":"Đúng rồi, đón sinh nhật thì phải ăn đồ ngon, lại còn phải chơi thật vui vẻ nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"长长的面条儿，大大的蛋糕。\" (Mì sợi dài, bánh kem to.) và \"你看，还有鱼啊肉啊什么的，都是你喜欢吃的。\" (Con xem, còn có cá, thịt các thứ nữa, đều là món con thích ăn.), nên đáp án đúng là 面条儿、蛋糕、鱼和肉等 (mì sợi, bánh kem, cá và thịt...).","options":["只有面条儿和蛋糕","面条儿、蛋糕、鱼和肉等","只有鱼和肉","面包、牛奶和水果"],"q":"今天小雪的生日有什么好吃的？"},{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói: \"吃完饭我们还要出去玩呢。\" (Ăn cơm xong chúng ta còn phải ra ngoài chơi nữa đấy.), nên đáp án đúng là 出去玩 (ra ngoài chơi).","options":["出去玩","在家画画","早早地上床睡觉","去商店买礼物"],"q":"吃完饭以后，他们打算做什么？"}],"scene":"在客厅，刘明一家人在给刘小雪过生日。","sceneVi":"Ở phòng khách, gia đình Lưu Minh đang tổ chức sinh nhật cho Lưu Tiểu Tuyết."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天是女儿的生日。","pinyin":"Jīntiān shì nǚ'ér de shēngrì.","speaker":"Đoạn văn","vi":"Hôm nay là sinh nhật của con gái."},{"hanzi":"我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。","pinyin":"Wǒmen mǎile dàngāo, zuòle miàntiáor, hái zuòle yú a ròu a shénmede.","speaker":"Đoạn văn","vi":"Chúng tôi đã mua bánh kem, làm mì sợi, còn nấu cá, thịt các thứ nữa."},{"hanzi":"吃完晚饭，一家人去看了个电影。","pinyin":"Chīwán wǎnfàn, yì jiā rén qù kànle gè diànyǐng.","speaker":"Đoạn văn","vi":"Ăn cơm tối xong, cả nhà đi xem một bộ phim."},{"hanzi":"回家后，孩子们早早地就上床了。","pinyin":"Huí jiā hòu, háizimen zǎozǎo de jiù shàng chuáng le.","speaker":"Đoạn văn","vi":"Sau khi về nhà, bọn trẻ đã lên giường đi ngủ từ sớm."},{"hanzi":"明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。","pinyin":"Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng.","speaker":"Đoạn văn","vi":"Ngày mai không phải đi học, chúng bảo muốn ngủ một giấc thật thoải mái và dặn chúng tôi gọi chúng dậy muộn một chút."},{"hanzi":"这是很忙、很累，但很快乐的一天。","pinyin":"Zhè shì hěn máng, hěn lèi, dàn hěn kuàilè de yì tiān.","speaker":"Đoạn văn","vi":"Đây là một ngày rất bận rộn, rất mệt nhưng vô cùng vui vẻ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"吃完晚饭，一家人去看了个电影。\" (Ăn tối xong, cả nhà đi xem một bộ phim.), nên đáp án đúng là 去看电影了 (đã đi xem phim).","options":["去商场购物了","去朋友家玩了","去看电影了","去公园跑步了"],"q":"吃完晚饭以后，一家人去做什么了？"},{"answerIdx":1,"explanation":"Trong bài có câu \"明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。\" (Ngày mai không phải đi học, bọn trẻ nói muốn ngủ một giấc thật thoải mái, bảo chúng tôi gọi chúng dậy muộn một chút.), nên đáp án đúng là 因为明天不上学，他们想好好睡一觉.","options":["因为他们生病了","因为明天不上学，他们想好好睡一觉","因为他们还要继续画画","因为明天要很早去学校"],"q":"为什么孩子们让爸爸妈妈明天晚点儿叫他们起床？"}],"scene":"在房间，王一雪在写日记。","sceneVi":"Ở trong phòng, Vương Nhất Tuyết đang viết nhật ký."}],"hsk2-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"安妮，你是什么时候从北京回来的？","pinyin":"Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?","speaker":"陈天中","vi":"An Ni, cậu từ Bắc Kinh về lúc nào vậy?"},{"hanzi":"昨天下午。天中，你怎么一下课就往外跑？","pinyin":"Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","speaker":"安妮","vi":"Chiều hôm qua. Thiên Trung, sao cậu vừa tan học đã chạy ra ngoài thế?"},{"hanzi":"我跟同学说好了，一起去打篮球。","pinyin":"Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú.","speaker":"陈天中","vi":"Tớ đã hẹn với bạn học rồi, cùng đi chơi bóng rổ."},{"hanzi":"我也想跟你们一起玩。","pinyin":"Wǒ yě xiǎng gēn nǐmen yìqǐ wán.","speaker":"安妮","vi":"Tớ cũng muốn đi chơi cùng các cậu."},{"hanzi":"没问题，走吧。","pinyin":"Méi wèntí, zǒu ba.","speaker":"陈天中","vi":"Không vấn đề gì, đi thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi được hỏi lúc nào từ Bắc Kinh trở về, An Ni trả lời: \"昨天下午。\" (Chiều hôm qua.), nên đáp án đúng là 昨天下午.","options":["今天上午","昨天下午","昨天上午","上个星期天"],"q":"安妮是什么时候从北京回来的？"},{"answerIdx":2,"explanation":"Trong bài, Trần Thiên Trung nói: \"我跟同学说好了，一起去打篮球。\" (Tớ đã hẹn với bạn học rồi, cùng đi chơi bóng rổ.), nên đáp án đúng là 因为他跟同学约好了一起打篮球.","options":["因为他要回家吃饭","因为他要去北京","因为他跟同学约好了一起打篮球","因为他要去游泳"],"q":"陈天中为什么一下课就往外跑？"}],"scene":"在教室，安妮和陈天中在聊天儿。","sceneVi":"Trong lớp học, An Ni và Trần Thiên Trung đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"天中，你是不是很喜欢打篮球？","pinyin":"Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?","speaker":"安妮","vi":"Thiên Trung, có phải cậu rất thích chơi bóng rổ không?"},{"hanzi":"没错。","pinyin":"Méi cuò.","speaker":"陈天中","vi":"Đúng vậy."},{"hanzi":"你还喜欢什么运动？","pinyin":"Nǐ hái xǐhuan shénme yùndòng?","speaker":"安妮","vi":"Cậu còn thích môn thể thao nào nữa?"},{"hanzi":"我还喜欢踢足球，一到星期天就跟朋友们去踢球。","pinyin":"Wǒ hái xǐhuan tī zúqiú, yí dào Xīngqītiān jiù gēn péngyoumen qù tī qiú.","speaker":"陈天中","vi":"Tớ còn thích đá bóng, cứ đến Chủ nhật là đi đá bóng với bạn bè."},{"hanzi":"你踢得怎么样？","pinyin":"Nǐ tī de zěnmeyàng?","speaker":"安妮","vi":"Cậu đá thế nào?"},{"hanzi":"我踢得还可以。","pinyin":"Wǒ tī de hái kěyǐ.","speaker":"陈天中","vi":"Tớ đá cũng tạm được."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"我还喜欢踢足球，一到星期天就跟朋友们去踢球。\" (Tớ còn thích đá bóng, cứ đến Chủ nhật là đi đá bóng cùng bạn bè.), nên đáp án đúng là 跟朋友们去踢足球.","options":["在家看电影","去北京看朋友","跟朋友们去踢足球","跟爸爸去跑步"],"q":"一到星期天，陈天中常做什么？"},{"answerIdx":0,"explanation":"Trong bài, khi An Ni hỏi \"你踢得怎么样？\" (Cậu đá thế nào?), Trần Thiên Trung trả lời: \"我踢得还可以。\" (Tớ đá cũng tạm được / khá ổn.), nên đáp án đúng là 踢得还可以.","options":["踢得还可以","踢得不太好","踢得非常慢","一点儿也不会踢"],"q":"陈天中觉得自己足球踢得怎么样？"}],"scene":"在校园，安妮和陈天中边走边聊。","sceneVi":"Trong khuôn viên trường, An Ni và Trần Thiên Trung vừa đi vừa trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你篮球打得怎么样？","pinyin":"Nǐ lánqiú dǎ de zěnmeyàng?","speaker":"陈天中","vi":"Cậu chơi bóng rổ thế nào?"},{"hanzi":"打得还可以。","pinyin":"Dǎ de hái kěyǐ.","speaker":"安妮","vi":"Chơi cũng tạm được."},{"hanzi":"跑步呢？你跑得快不快？","pinyin":"Pǎobù ne? Nǐ pǎo de kuài bu kuài?","speaker":"陈天中","vi":"Còn chạy bộ thì sao? Cậu chạy có nhanh không?"},{"hanzi":"我跑得不快，也不太喜欢跑步。","pinyin":"Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù.","speaker":"安妮","vi":"Tớ chạy không nhanh, cũng không thích chạy bộ lắm."},{"hanzi":"那你喜欢游泳吗？","pinyin":"Nà nǐ xǐhuan yóuyǒng ma?","speaker":"陈天中","vi":"Vậy cậu có thích bơi lội không?"},{"hanzi":"喜欢，但我游泳游得不快。","pinyin":"Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài.","speaker":"安妮","vi":"Thích, nhưng tớ bơi không nhanh."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, An Ni nói: \"我跑得不快，也不太喜欢跑步。\" (Tớ chạy không nhanh, cũng không thích chạy bộ lắm.), nên đáp án đúng là 她跑得不快，也不太喜欢跑步.","options":["她跑得很快，也很喜欢跑步","她跑得不快，也不太喜欢跑步","她每天都去跑步","她跑得还可以，但是没时间跑"],"q":"关于跑步，安妮是怎么说的？"},{"answerIdx":2,"explanation":"Trong bài, khi được hỏi có thích bơi không, An Ni đáp: \"喜欢，但我游泳游得不快。\" (Thích, nhưng tớ bơi không nhanh.), nên đáp án đúng là 她喜欢游泳，但是游得不快.","options":["她不喜欢游泳，游得也不快","她喜欢游泳，而且游得非常快","她喜欢游泳，但是游得不快","她不会游泳，只喜欢打篮球"],"q":"安妮喜欢游泳吗？她游得怎么样？"}],"scene":"在校园，安妮和陈天中边走边聊。","sceneVi":"Trong khuôn viên trường, An Ni và Trần Thiên Trung vừa đi vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我的爱好是运动。","pinyin":"Wǒ de àihào shì yùndòng.","speaker":"Đoạn văn","vi":"Sở thích của tôi là thể thao."},{"hanzi":"从上小学开始，我每天都跟爸爸去运动。","pinyin":"Cóng shàng xiǎoxué kāishǐ, wǒ měi tiān dōu gēn bàba qù yùndòng.","speaker":"Đoạn văn","vi":"Từ khi học tiểu học, ngày nào tôi cũng đi tập thể thao cùng bố."},{"hanzi":"现在我篮球打得很好，足球踢得不错，游泳游得也很快。","pinyin":"Xiànzài wǒ lánqiú dǎ de hěn hǎo, zúqiú tī de búcuò, yóuyǒng yóu de yě hěn kuài.","speaker":"Đoạn văn","vi":"Bây giờ tôi chơi bóng rổ rất giỏi, đá bóng khá tốt, bơi cũng rất nhanh."},{"hanzi":"我一有时间就去运动。","pinyin":"Wǒ yì yǒu shíjiān jiù qù yùndòng.","speaker":"Đoạn văn","vi":"Cứ hễ có thời gian là tôi lại đi tập thể thao."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài có câu \"从上小学开始，我每天都跟爸爸去运动。\" (Từ khi học tiểu học, ngày nào tôi cũng đi tập thể thao cùng bố.), nên đáp án đúng là 跟爸爸 (cùng bố).","options":["跟同学","跟安妮","跟哥哥","跟爸爸"],"q":"从上小学开始，陈天中每天都跟谁一起去运动？"},{"answerIdx":1,"explanation":"Trong bài có câu \"现在我篮球打得很好，足球踢得不错，游泳游得也很快。\" (Hiện tại tôi chơi bóng rổ rất giỏi, đá bóng khá tốt, bơi lội cũng rất nhanh.), nên đáp án đúng là 陈天中现在篮球、足球和游泳都很好.","options":["陈天中游泳游得不快","陈天中现在篮球、足球和游泳都很好","陈天中只有星期天才去运动","陈天中不太喜欢运动"],"q":"下面哪句话符合日记的内容？"}],"scene":"在房间，陈天中在写日记。","sceneVi":"Trong phòng, Trần Thiên Trung đang viết nhật ký."}],"hsk2-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你看，这两块手表怎么样？","pinyin":"Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?","speaker":"王一雪","vi":"Anh xem, hai chiếc đồng hồ đeo tay này thế nào?"},{"hanzi":"都不错！","pinyin":"Dōu búcuò!","speaker":"刘明","vi":"Cả hai đều đẹp!"},{"hanzi":"我喜欢左边这个。","pinyin":"Wǒ xǐhuan zuǒbian zhège.","speaker":"王一雪","vi":"Em thích chiếc bên trái này."},{"hanzi":"我也觉得左边的比右边的好看。","pinyin":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","speaker":"刘明","vi":"Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải."},{"hanzi":"你看看要多少钱！","pinyin":"Nǐ kànkan yào duōshao qián!","speaker":"王一雪","vi":"Anh xem thử giá bao nhiêu tiền!"},{"hanzi":"真不便宜！八千八！","pinyin":"Zhēn bù piányi! Bā qiān bā!","speaker":"刘明","vi":"Thật không rẻ chút nào! Tám nghìn tám!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我喜欢左边这个。\" (Em thích chiếc bên trái này.) và Lưu Minh cũng đồng ý \"我也觉得左边的比右边的好看。\" (Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải.), nên đáp án đúng là 左边那块 (chiếc bên trái).","options":["右边那块","左边那块","两块都不好看","最便宜的那块"],"q":"王一雪和刘明都觉得哪块手表更好看？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói: \"真不便宜！八千八！\" (Thật không rẻ chút nào! Tám nghìn tám!), nên đáp án đúng là 八千八 (8.800).","options":["八百八","八千块","八千八","非常便宜"],"q":"他们看的手表多少钱？"}],"scene":"在商场，王一雪和刘明在购物。","sceneVi":"Ở trung tâm thương mại, Vương Nhất Tuyết và Lưu Minh đang mua sắm."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"今天有不少电影，我们看个电影吧。","pinyin":"Jīntiān yǒu bù shǎo diànyǐng, wǒmen kàn gè diànyǐng ba.","speaker":"刘明","vi":"Hôm nay có khá nhiều phim, chúng ta xem một bộ phim đi."},{"hanzi":"好啊！我们看哪个？","pinyin":"Hǎo a! Wǒmen kàn nǎge?","speaker":"王一雪","vi":"Được đấy! Chúng ta xem phim nào?"},{"hanzi":"我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","pinyin":"Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","speaker":"刘明","vi":"Anh nhớ em thích xem phim tình cảm, chúng ta xem bộ phim tình cảm kia nhé, thế nào?"},{"hanzi":"还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","pinyin":"Háishi kàn zhège ba, wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","speaker":"王一雪","vi":"Hay là xem bộ này đi, em thấy trên mạng nói bộ phim này hay hơn bộ phim tình cảm kia đấy."},{"hanzi":"好。我去买票。","pinyin":"Hǎo. Wǒ qù mǎi piào.","speaker":"刘明","vi":"Được. Anh đi mua vé."},{"hanzi":"到网上买吧，网上买比在这里买便宜。","pinyin":"Dào wǎngshang mǎi ba, wǎngshang mǎi bǐ zài zhèlǐ mǎi piányi.","speaker":"王一雪","vi":"Mua trên mạng đi anh, mua trên mạng rẻ hơn mua ở đây."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói: \"我看网上说这个电影比那个爱情片更有意思。\" (Em thấy trên mạng nói bộ phim này thú vị hơn bộ phim tình cảm kia.), nên đáp án đúng là 因为网上说这个电影比那个爱情片更有意思.","options":["因为这个电影的票更便宜","因为她不喜欢看爱情片","因为网上说这个电影比那个爱情片更有意思","因为那个爱情片今天不演"],"q":"王一雪为什么想看这个电影，不想看那个爱情片？"},{"answerIdx":1,"explanation":"Trong bài có câu \"到网上买吧，网上买比在这里买便宜。\" (Lên mạng mua đi anh, mua trên mạng rẻ hơn mua ở đây.), nên đáp án đúng là 在网上买，因为比在电影院买便宜.","options":["在电影院买，因为更快","在网上买，因为比在电影院买便宜","请朋友买，因为不用花钱","在商场买，因为有礼物送"],"q":"王一雪建议在哪里买电影票？为什么？"}],"scene":"在电影院外面，王一雪和刘明在聊天儿。","sceneVi":"Bên ngoài rạp chiếu phim, Vương Nhất Tuyết và Lưu Minh đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"您好！就要这几个菜吧，谢谢！","pinyin":"Nín hǎo! Jiù yào zhè jǐ gè cài ba, xièxie!","speaker":"刘明","vi":"Xin chào! Lấy mấy món này nhé, cảm ơn!"},{"hanzi":"怎么点这么多菜？","pinyin":"Zěnme diǎn zhème duō cài?","speaker":"王一雪","vi":"Sao anh gọi nhiều món thế?"},{"hanzi":"你想想，今天是几月几号？","pinyin":"Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?","speaker":"刘明","vi":"Em nghĩ xem, hôm nay là ngày mấy tháng mấy?"},{"hanzi":"8月27号。啊！我的生日！","pinyin":"Bā yuè èrshíqī hào. À! Wǒ de shēngrì!","speaker":"王一雪","vi":"Ngày 27 tháng 8. À! Sinh nhật của em!"},{"hanzi":"生日快乐！虽然你忘了，但是我记得。看看这是什么？","pinyin":"Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?","speaker":"刘明","vi":"Chúc mừng sinh nhật! Tuy em quên rồi, nhưng anh vẫn nhớ. Xem thử đây là gì nào?"},{"hanzi":"手表！吃饭、看电影、买手表，今天花了不少钱吧？","pinyin":"Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huā le bù shǎo qián ba?","speaker":"王一雪","vi":"Đồng hồ đeo tay! Ăn cơm, xem phim, mua đồng hồ, hôm nay tiêu không ít tiền rồi đúng không?"},{"hanzi":"虽然花了一些钱，但是我们过了一个快乐的生日。","pinyin":"Suīrán huā le yìxiē qián, dànshì wǒmen guò le yí gè kuàilè de shēngrì.","speaker":"刘明","vi":"Tuy có tiêu một ít tiền, nhưng chúng ta đã đón một ngày sinh nhật vui vẻ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có đoạn \"你想想，今天是几月几号？\" - \"8月27号。啊！我的生日！\" (Em nghĩ xem, hôm nay ngày mấy tháng mấy? - Ngày 27 tháng 8. A! Sinh nhật của em!), nên đáp án đúng là 八月二十七号 (ngày 27 tháng 8).","options":["七月二十八号","八月二十七号","八月十七号","九月二十七号"],"q":"王一雪的生日是几月几号？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói: \"生日快乐！虽然你忘了，但是我记得。看看这是什么？\" (Chúc mừng sinh nhật! Tuy em quên nhưng anh vẫn nhớ. Xem đây là gì nào?), nên đáp án đúng là 因为今天是王一雪的生日.","options":["因为今天有很多朋友来吃饭","因为饭馆今天的菜很便宜","因为今天是王一雪的生日","因为刘明今天忘了带礼物"],"q":"刘明为什么点这么多菜，还买了手表？"}],"scene":"在饭馆，王一雪和刘明在点菜。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết và Lưu Minh đang gọi món."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"虽然妻子忘了今天是自己的生日，但是丈夫记得。","pinyin":"Suīrán qīzi wàng le jīntiān shì zìjǐ de shēngrì, dànshì zhàngfu jìde.","speaker":"Đoạn văn","vi":"Tuy người vợ quên hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ."},{"hanzi":"丈夫请妻子去饭馆吃饭、去电影院看电影，还给妻子买了一块非常漂亮的手表。","pinyin":"Zhàngfu qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng, hái gěi qīzi mǎi le yí kuài fēicháng piàoliang de shǒubiǎo.","speaker":"Đoạn văn","vi":"Người chồng mời vợ đi nhà hàng ăn cơm, đi rạp chiếu phim xem phim, lại còn mua tặng vợ một chiếc đồng hồ đeo tay vô cùng đẹp."},{"hanzi":"妻子觉得今天很快乐。","pinyin":"Qīzi juéde jīntiān hěn kuàilè.","speaker":"Đoạn văn","vi":"Người vợ cảm thấy hôm nay rất vui vẻ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong đoạn văn có câu \"虽然妻子忘了今天是自己的生日，但是丈夫记得。\" (Tuy người vợ quên hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ.), nên đáp án đúng là 妻子忘了 (người vợ quên).","options":["丈夫忘了","妻子忘了","两个人都忘了","小语忘了"],"q":"这段话里，谁忘了今天是自己的生日？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu \"丈夫请妻子去饭馆吃饭、去电影院看电影，还给妻子买了一块非常漂亮的手表。\" (Người chồng mời vợ đi nhà hàng ăn cơm, đi rạp chiếu phim xem phim, còn mua tặng vợ một chiếc đồng hồ rất đẹp.), không nhắc đến việc mua quần áo mới, nên đáp án đúng là 给她买了一件新衣服.","options":["请她去饭馆吃饭","请她去看电影","给她买了一块手表","给她买了一件新衣服"],"q":"那一天，丈夫没有为妻子做什么？"}],"scene":"小语在讲述王一雪和刘明的一天。","sceneVi":"Tiểu Ngữ đang kể lại một ngày của Vương Nhất Tuyết và Lưu Minh."}],"hsk2-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"儿子的裤子坏了，我们给他买条新的吧。","pinyin":"Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba.","speaker":"王一雪","vi":"Quần của con trai hỏng rồi, chúng ta mua cho con một cái mới nhé."},{"hanzi":"好啊。","pinyin":"Hǎo a.","speaker":"刘明","vi":"Được thôi."},{"hanzi":"你看这条黑色的怎么样？","pinyin":"Nǐ kàn zhè tiáo hēisè de zěnmeyàng?","speaker":"王一雪","vi":"Anh xem cái màu đen này thế nào?"},{"hanzi":"没有你上次买的那条好看。","pinyin":"Méiyǒu nǐ shàng cì mǎi de nà tiáo hǎokàn.","speaker":"刘明","vi":"Không đẹp bằng cái lần trước em mua."},{"hanzi":"旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","pinyin":"Pángbiān nàge nánháir jiù chuānle zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","speaker":"王一雪","vi":"Cậu bé bên cạnh mặc quần giống thế này đấy, em thấy rất đẹp mà!"},{"hanzi":"儿子的个子没有他那么高，穿上就不会太好看。","pinyin":"Érzi de gèzi méiyǒu tā nàme gāo, chuānshàng jiù bú huì tài hǎokàn.","speaker":"刘明","vi":"Vóc dáng của con trai mình không cao bằng cậu bé ấy, mặc vào sẽ không đẹp lắm đâu."},{"hanzi":"好吧，我们再去那边看看。","pinyin":"Hǎo ba, wǒmen zài qù nàbiān kànkan.","speaker":"王一雪","vi":"Được rồi, chúng ta qua bên kia xem thêm đi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói: \"儿子的裤子坏了，我们给他买条新的吧。\" (Quần của con trai hỏng rồi, chúng ta mua cho con một chiếc mới đi.), nên đáp án đúng là 因为儿子的裤子坏了.","options":["因为今天是儿子的生日","因为儿子的裤子坏了","因为儿子喜欢黑色的裤子","因为商店的裤子很便宜"],"q":"他们为什么要给儿子买新裤子？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nhận xét: \"没有你上次买的那条好看。\" (Không đẹp bằng chiếc lần trước em mua.) và \"儿子的个子没有他那么高，穿上就不会太好看。\" (Con trai không cao bằng cậu bé kia, mặc vào sẽ không đẹp lắm đâu.), nên đáp án đúng là 他觉得没有上次买的那条好看，儿子个子不够高.","options":["他觉得比上次买的那条好看","他觉得儿子穿上一定很好看","他觉得没有上次买的那条好看，儿子个子不够高","他觉得这条裤子太贵了"],"q":"关于那条黑色的裤子，刘明怎么看？"}],"scene":"在商店，王一雪和刘明在看裤子。","sceneVi":"Ở cửa hàng, Vương Nhất Tuyết và Lưu Minh đang xem quần."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"门口有家奶茶店。你想喝杯奶茶吗？","pinyin":"Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?","speaker":"王一雪","vi":"Ngay cửa có một quán trà sữa. Anh có muốn uống một ly trà sữa không?"},{"hanzi":"我想喝咖啡，还是去咖啡店吧。","pinyin":"Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba.","speaker":"刘明","vi":"Anh muốn uống cà phê, hay là đi quán cà phê đi."},{"hanzi":"咖啡店离这儿有点儿远。","pinyin":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","speaker":"王一雪","vi":"Quán cà phê cách đây hơi xa."},{"hanzi":"没关系，那家店的咖啡很好喝。","pinyin":"Méi guānxi, nà jiā diàn de kāfēi hěn hǎo hē.","speaker":"刘明","vi":"Không sao đâu, cà phê ở quán đó rất ngon."},{"hanzi":"那你等一下，我去买杯奶茶。","pinyin":"Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá.","speaker":"王一雪","vi":"Vậy anh đợi một chút, em đi mua ly trà sữa."},{"hanzi":"你不想喝咖啡吗？","pinyin":"Nǐ bù xiǎng hē kāfēi ma?","speaker":"刘明","vi":"Em không muốn uống cà phê à?"},{"hanzi":"喝了咖啡，晚上就别想睡觉了。","pinyin":"Hēle kāfēi, wǎnshang jiù bié xiǎng shuìjiào le.","speaker":"王一雪","vi":"Uống cà phê rồi thì tối đừng hòng ngủ được."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói: \"我想喝咖啡，还是去咖啡店吧。\" (Anh muốn uống cà phê, hay là đi quán cà phê đi.), nên đáp án đúng là 去那家咖啡店 (đến quán cà phê kia).","options":["去门口的奶茶店","去那家咖啡店","直接回家睡觉","去大商场看衣服"],"q":"从商店出来后，刘明想去哪儿？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết giải thích: \"喝了咖啡，晚上就别想睡觉了。\" (Uống cà phê rồi thì buổi tối đừng hòng ngủ được.), nên đáp án đúng là 因为喝了咖啡，她晚上就睡不着了.","options":["因为那家店的咖啡不好喝","因为咖啡太贵了","因为喝了咖啡，她晚上就睡不着了","因为咖啡店关门了"],"q":"王一雪为什么不想喝咖啡？"}],"scene":"在商店门口，王一雪和刘明往外走。","sceneVi":"Ở cửa cửa hàng, Vương Nhất Tuyết và Lưu Minh đang đi ra ngoài."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"我们打车回去吧。","pinyin":"Wǒmen dǎchē huíqù ba.","speaker":"刘明","vi":"Chúng ta bắt taxi về đi."},{"hanzi":"这里离家很近，还是走路吧。","pinyin":"Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba.","speaker":"王一雪","vi":"Ở đây cách nhà rất gần, hay là đi bộ đi."},{"hanzi":"要走多长时间？","pinyin":"Yào zǒu duō cháng shíjiān?","speaker":"刘明","vi":"Phải đi bộ mất bao lâu?"},{"hanzi":"走半个多小时就到了。","pinyin":"Zǒu bàn gè duō xiǎoshí jiù dào le.","speaker":"王一雪","vi":"Đi hơn nửa tiếng là tới rồi."},{"hanzi":"好的。每天上下班都坐车，今天运动运动吧。","pinyin":"Hǎo de. Měi tiān shàng xià bān dōu zuò chē, jīntiān yùndòng yùndòng ba.","speaker":"刘明","vi":"Được đấy. Ngày nào đi làm và tan làm cũng ngồi xe, hôm nay vận động một chút đi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết trả lời: \"走半个多小时就到了。\" (Đi bộ hơn nửa tiếng là tới rồi.), nên đáp án đúng là 半个多小时 (hơn nửa tiếng).","options":["十分钟左右","半个多小时","两个小时","一刻钟"],"q":"王一雪说从这里走路回家要多长时间？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói: \"好的。每天上下班都坐车，今天运动运动吧。\" (Được thôi. Ngày nào đi làm cũng ngồi xe, hôm nay vận động một chút đi.), nên đáp án đúng là 因为他每天坐车上下班，想借机运动运动.","options":["因为打车太贵了","因为外面打不到车","因为他每天坐车上下班，想借机运动运动","因为他想在路上再买件衣服"],"q":"刘明最后为什么同意走路回家？"}],"scene":"在咖啡店门口，王一雪和刘明在聊天儿。","sceneVi":"Ở cửa quán cà phê, Vương Nhất Tuyết và Lưu Minh đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这周刘明休息，我下班后跟他去了一家商店。","pinyin":"Zhè zhōu Liú Míng xiūxi, wǒ xiàbān hòu gēn tā qùle yì jiā shāngdiàn.","speaker":"Đoạn văn","vi":"Tuần này Lưu Minh nghỉ làm, sau khi tan làm tôi đã cùng anh ấy đi một cửa hàng."},{"hanzi":"商店里边的衣服没有大商场里的好看。","pinyin":"Shāngdiàn lǐbian de yīfu méiyǒu dà shāngchǎng lǐ de hǎokàn.","speaker":"Đoạn văn","vi":"Quần áo bên trong cửa hàng không đẹp bằng ở trung tâm thương mại lớn."},{"hanzi":"我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。","pinyin":"Wǒmen méiyǒu mǎidào xǐhuan de yīfu, cóng shāngdiàn chūlái jiù dào kāfēidiàn zuòle zuò.","speaker":"Đoạn văn","vi":"Chúng tôi không mua được bộ quần áo nào ưng ý, ra khỏi cửa hàng liền đến quán cà phê ngồi một lát."},{"hanzi":"因为想运动运动，所以喝完东西，我们就走回家了。","pinyin":"Yīnwèi xiǎng yùndòng yùndòng, suǒyǐ hēwán dōngxi, wǒmen jiù zǒuhuí jiā le.","speaker":"Đoạn văn","vi":"Vì muốn vận động một chút, nên uống xong nước, chúng tôi đã đi bộ về nhà."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。\" (Chúng tôi không mua được quần áo ưng ý, ra khỏi cửa hàng liền đến quán cà phê ngồi một lát.), nên đáp án đúng là 没有买到喜欢的衣服.","options":["买到了很多好看的衣服","没有买到喜欢的衣服","只买了一条黑色的裤子","买了一块漂亮的手表"],"q":"王一雪和刘明在商店买到喜欢的衣服了吗？"},{"answerIdx":2,"explanation":"Trong bài có câu \"因为想运动运动，所以喝完东西，我们就走回家了。\" (Vì muốn vận động một chút nên uống xong đồ uống, chúng tôi liền đi bộ về nhà.), nên đáp án đúng là 走路回家的 (đi bộ về nhà).","options":["打车回家的","坐公共汽车回家的","走路回家的","骑自行车回家的"],"q":"从咖啡店喝完东西后，他们是怎么回家的？"}],"scene":"在房间，王一雪在写日记。","sceneVi":"Trong phòng, Vương Nhất Tuyết đang viết nhật ký."}],"hsk2-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"小明，你们明天开学，你准备好了吗？","pinyin":"Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?","speaker":"刘明","vi":"Tiểu Minh, ngày mai các con khai giảng rồi, con đã chuẩn bị xong chưa?"},{"hanzi":"明天就开学啊？爸爸，我的书包你看见了吗？","pinyin":"Míngtiān jiù kāixué a? Bàba, wǒ de shūbāo nǐ kànjiànle ma?","speaker":"刘小明","vi":"Ngày mai đã khai giảng rồi ạ? Bố ơi, bố có thấy cặp sách của con đâu không?"},{"hanzi":"书包在门后面。","pinyin":"Shūbāo zài mén hòumiàn.","speaker":"刘明","vi":"Cặp sách ở đằng sau cửa."},{"hanzi":"书在哪儿呢？笔呢？","pinyin":"Shū zài nǎr ne? Bǐ ne?","speaker":"刘小明","vi":"Sách ở đâu ạ? Còn bút nữa ạ?"},{"hanzi":"书在床上，笔在桌子上。","pinyin":"Shū zài chuáng shang, bǐ zài zhuōzi shang.","speaker":"刘明","vi":"Sách ở trên giường, bút ở trên bàn."},{"hanzi":"太好了！现在都准备好了。","pinyin":"Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le.","speaker":"刘小明","vi":"Tuyệt quá! Bây giờ đều chuẩn bị xong hết rồi ạ."},{"hanzi":"这次爸爸帮你，下次你自己准备，好不好？","pinyin":"Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?","speaker":"刘明","vi":"Lần này bố giúp con, lần sau con tự chuẩn bị nhé, được không?"},{"hanzi":"好！","pinyin":"Hǎo!","speaker":"刘小明","vi":"Vâng ạ!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh đã nói với con trai \"书包在门后面。\" (Cặp sách ở phía sau cửa), còn sách ở trên giường và bút ở trên bàn, nên đáp án đúng là 在门后面.","options":["在床上","在门后面","在桌子上","在椅子下面"],"q":"刘小明的书包在哪儿？"},{"answerIdx":2,"explanation":"Trong bài có câu \"这次爸爸帮你，下次你自己准备，好不好？\" (Lần này bố giúp con, lần sau con tự chuẩn bị, được không?), nên lần sau Lưu Tiểu Minh phải tự chuẩn bị đồ dùng học tập của mình.","options":["让姐姐帮他准备","买新的书包和笔","自己准备学习的东西","早一点儿去学校"],"q":"爸爸让刘小明下次怎么做？"}],"scene":"在房间，刘明在帮刘小明准备东西。","sceneVi":"Trong phòng, Lưu Minh đang giúp Lưu Tiểu Minh chuẩn bị đồ đạc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"小雪，你在做什么呢？","pinyin":"Xiǎoxuě, nǐ zài zuò shénme ne?","speaker":"王一雪","vi":"Tiểu Tuyết, con đang làm gì thế?"},{"hanzi":"明天考试，我在看书呢。","pinyin":"Míngtiān kǎoshì, wǒ zài kàn shū ne.","speaker":"刘小雪","vi":"Ngày mai thi rồi, con đang đọc sách ạ."},{"hanzi":"这些词要好好看看。","pinyin":"Zhèxiē cí yào hǎohǎo kànkan.","speaker":"王一雪","vi":"Những từ này phải xem cho kỹ vào."},{"hanzi":"我看过了，意思也都懂了。","pinyin":"Wǒ kànguo le, yìsi yě dōu dǒng le.","speaker":"刘小雪","vi":"Con xem qua rồi, nghĩa cũng hiểu hết rồi ạ."},{"hanzi":"你的本子呢？本子上做错的题也要看一看。","pinyin":"Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào kàn yi kàn.","speaker":"王一雪","vi":"Vở của con đâu? Những câu làm sai trong vở cũng phải xem lại một chút."},{"hanzi":"妈妈，是您准备考试还是我准备考试？","pinyin":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","speaker":"刘小雪","vi":"Mẹ ơi, là mẹ chuẩn bị thi hay con chuẩn bị thi vậy ạ?"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, mẹ Vương Nhất Tuyết nói \"你的本子呢？本子上做错的题也要看一看。\" (Vở của con đâu? Những câu làm sai trên vở cũng phải xem qua một chút), nên ngoài từ mới còn phải xem lại câu làm sai trên vở.","options":["本子上做错的题","昨天的报纸","新的中文书","弟弟的本子"],"q":"除了这些词以外，妈妈还让小雪看什么？"},{"answerIdx":0,"explanation":"Trong bài, Tiểu Tuyết đã xem sách và hiểu hết nghĩa các từ mới (\"我看过了，意思也都懂了。\"), nhưng mẹ vẫn liên tục dặn xem cái này cái kia nên cô bé nói đùa hỏi lại như vậy vì mẹ cứ nhắc mãi.","options":["因为妈妈一直告诉她要看什么","因为妈妈明天也要考试","因为她没有看懂这些词","因为她找不到自己的本子"],"q":"小雪为什么问“是您准备考试还是我准备考试”？"}],"scene":"在房间，王一雪和刘小雪在聊学习。","sceneVi":"Trong phòng, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang nói chuyện học hành."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"妈妈，我回来了！","pinyin":"Māma, wǒ huílái le!","speaker":"刘小雪","vi":"Mẹ ơi, con về rồi ạ!"},{"hanzi":"我买了奶茶，就在桌子上，自己去拿吧。","pinyin":"Wǒ mǎile nǎichá, jiù zài zhuōzi shang, zìjǐ qù ná ba.","speaker":"王一雪","vi":"Mẹ có mua trà sữa đấy, ở ngay trên bàn, tự ra lấy đi con."},{"hanzi":"谢谢妈妈！","pinyin":"Xièxie māma!","speaker":"刘小雪","vi":"Con cảm ơn mẹ ạ!"},{"hanzi":"今天考试考得怎么样？","pinyin":"Jīntiān kǎoshì kǎo de zěnmeyàng?","speaker":"王一雪","vi":"Hôm nay con thi thế nào?"},{"hanzi":"我觉得比上次好。","pinyin":"Wǒ juéde bǐ shàng cì hǎo.","speaker":"刘小雪","vi":"Con thấy làm tốt hơn lần trước ạ."},{"hanzi":"真不错！饭菜快要做好了，你叫弟弟一起去洗手吧。","pinyin":"Zhēn búcuò! Fàncài kuàiyào zuòhǎo le, nǐ jiào dìdi yìqǐ qù xǐshǒu ba.","speaker":"王一雪","vi":"Giỏi lắm! Cơm sắp nấu xong rồi, con gọi em trai cùng đi rửa tay đi."},{"hanzi":"妈妈，我是第一名，姐姐还没洗完呢。","pinyin":"Māma, wǒ shì dì-yī míng, jiějie hái méi xǐwán ne.","speaker":"刘小明","vi":"Mẹ ơi, con về nhất rồi, chị vẫn chưa rửa xong đâu ạ."},{"hanzi":"你洗得真快啊！","pinyin":"Nǐ xǐ de zhēn kuài a!","speaker":"王一雪","vi":"Con rửa nhanh thật đấy!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi mẹ hỏi bài thi hôm nay thế nào, Lưu Tiểu Tuyết trả lời \"我觉得比上次好。\" (Con thấy tốt hơn lần trước), nên đáp án đúng là 比上次考得好.","options":["比上次差一点儿","比上次考得好","和上次一样","题太多，没做完"],"q":"刘小雪觉得今天的考试怎么样？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Tiểu Minh khoe với mẹ \"妈妈，我是第一名，姐姐还没洗完呢。\" (Mẹ ơi, con về nhất rồi, chị vẫn chưa rửa xong đâu) và được mẹ khen rửa rất nhanh, nên em trai rửa xong trước chị gái.","options":["妈妈洗得最快","姐姐比弟弟先洗完","弟弟比姐姐先洗完","他们两个一起洗完"],"q":"姐姐和弟弟去洗手的时候，谁洗得更快？"}],"scene":"在客厅，王一雪和孩子们在聊天儿。","sceneVi":"Ở phòng khách, Vương Nhất Tuyết và các con đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"快要开学了，爸爸帮弟弟准备书包、本子和笔。","pinyin":"Kuàiyào kāixué le, bàba bāng dìdi zhǔnbèi shūbāo, běnzi hé bǐ.","speaker":"Đoạn văn","vi":"Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút."},{"hanzi":"我就要考试了，妈妈让我看书、看做错的题。","pinyin":"Wǒ jiù yào kǎoshì le, māma ràng wǒ kàn shū, kàn zuòcuò de tí.","speaker":"Đoạn văn","vi":"Tôi sắp thi rồi, mẹ bảo tôi đọc sách và xem lại những câu làm sai."},{"hanzi":"我们上学，爸爸、妈妈比我们还忙。","pinyin":"Wǒmen shàngxué, bàba, māma bǐ wǒmen hái máng.","speaker":"Đoạn văn","vi":"Chúng tôi đi học, bố mẹ còn bận rộn hơn cả chúng tôi."},{"hanzi":"我问他们：“是我和弟弟上学还是你们上学？”","pinyin":"Wǒ wèn tāmen: “Shì wǒ hé dìdi shàngxué háishi nǐmen shàngxué?”","speaker":"Đoạn văn","vi":"Tôi hỏi bố mẹ: “Là con và em trai đi học hay là bố mẹ đi học vậy ạ?”"},{"hanzi":"我问完，他们都笑了。","pinyin":"Wǒ wènwán, tāmen dōu xiào le.","speaker":"Đoạn văn","vi":"Tôi hỏi xong, bố mẹ đều bật cười."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"快要开学了，爸爸帮弟弟准备书包、本子和笔。\" (Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút), nên lý do là vì em trai sắp khai giảng.","options":["因为弟弟快要开学了","因为弟弟的书包丢了","因为弟弟明天要考试","因为弟弟今天去买东西"],"q":"爸爸为什么帮弟弟准备书包、本子和笔？"},{"answerIdx":1,"explanation":"Trong bài, thấy bố mẹ còn bận rộn hơn hai chị em, Tiểu Tuyết hỏi đùa \"是我和弟弟上学还是你们上学？\" (Là con và em trai đi học hay là bố mẹ đi học ạ?), và \"我问完，他们都笑了。\" (Con hỏi xong, bố mẹ đều bật cười) vì câu hỏi rất thú vị.","options":["因为弟弟考试考了第一名","因为小雪的问题很有意思","因为他们买到了好喝的奶茶","因为小雪不用去上学了"],"q":"日记的最后，爸爸和妈妈为什么都笑了？"}],"scene":"在房间，刘小雪在写日记。","sceneVi":"Trong phòng, Lưu Tiểu Tuyết đang viết nhật ký."}],"hsk2-11":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，都下课了，你怎么还不回家？","pinyin":"Jiāyuè, dōu xiàkè le, nǐ zěnme hái bù huí jiā?","speaker":"王一飞","vi":"Gia Nguyệt, tan học cả rồi, sao em vẫn chưa về nhà?"},{"hanzi":"我头疼，不太舒服。","pinyin":"Wǒ tóu téng, bú tài shūfu.","speaker":"白家月","vi":"Em bị đau đầu, không được khỏe lắm."},{"hanzi":"你这几天经常头疼，去医院看看吧。","pinyin":"Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba.","speaker":"王一飞","vi":"Mấy hôm nay em hay bị đau đầu, đi bệnh viện khám xem sao nhé."},{"hanzi":"我想休息一下，现在不能动，一动就疼。","pinyin":"Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng.","speaker":"白家月","vi":"Em muốn nghỉ ngơi một chút, bây giờ không cử động được, cứ cử động là đau."},{"hanzi":"那你在这儿坐着，我去开车，一会儿送你去医院。","pinyin":"Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yíhuìr sòng nǐ qù yīyuàn.","speaker":"王一飞","vi":"Vậy em ngồi đây đi, cô đi lấy xe, lát nữa đưa em đi bệnh viện."},{"hanzi":"谢谢王老师。","pinyin":"Xièxie Wáng lǎoshī.","speaker":"白家月","vi":"Cảm ơn cô Vương ạ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói với cô Vương \"我头疼，不太舒服。\" (Em bị đau đầu, không được khỏe lắm) và muốn ngồi nghỉ vì hễ cử động là đau.","options":["因为她在等李文一起走","因为她头疼，身体不太舒服","因为她要在教室写作业","因为外面正在下大雨"],"q":"下课以后，白家月为什么还没回家？"},{"answerIdx":2,"explanation":"Trong bài, cô Vương Nhất Phi nói \"那你在这儿坐着，我去开车，一会儿送你去医院。\" (Vậy em ngồi đây nhé, cô đi lấy xe, lát nữa đưa em đi bệnh viện), nên cô sẽ lái xe đưa Gia Nguyệt đi bệnh viện.","options":["去药店帮她买药","给她的妈妈打电话","开车送她去医院","陪她在教室休息"],"q":"王老师打算怎么帮助白家月？"}],"scene":"在教室，王一飞和白家月在聊天儿。","sceneVi":"Trong phòng học, Vương Nhất Phi và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"现在路上车多，还下着雪，我开慢一点儿。","pinyin":"Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr.","speaker":"王一飞","vi":"Bây giờ trên đường nhiều xe, trời lại đang có tuyết rơi, cô lái chậm một chút."},{"hanzi":"没问题，现在头没那么疼了。","pinyin":"Méi wèntí, xiànzài tóu méi nàme téng le.","speaker":"白家月","vi":"Không sao đâu ạ, bây giờ đầu em đỡ đau hơn nhiều rồi."},{"hanzi":"好。李文来电话了，你帮我接一下。","pinyin":"Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià.","speaker":"王一飞","vi":"Được. Lý Văn gọi điện tới kìa, em nghe máy giúp cô với."},{"hanzi":"喂，李文，王老师开着车呢，你找她有事吗？","pinyin":"Wèi, Lǐ Wén, Wáng lǎoshī kāizhe chē ne, nǐ zhǎo tā yǒu shì ma?","speaker":"白家月","vi":"Alo, Lý Văn à, cô Vương đang lái xe, cậu tìm cô có việc gì không?"},{"hanzi":"没什么事。今天雪这么大，你们开车去哪儿啊？","pinyin":"Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?","speaker":"李文","vi":"Không có việc gì quan trọng đâu. Hôm nay tuyết rơi to thế này, hai người lái xe đi đâu vậy?"},{"hanzi":"去医院，我头有点儿疼。","pinyin":"Qù yīyuàn, wǒ tóu yǒudiǎnr téng.","speaker":"白家月","vi":"Đi bệnh viện, mình hơi đau đầu một chút."},{"hanzi":"那我一会儿去看看你。","pinyin":"Nà wǒ yíhuìr qù kànkan nǐ.","speaker":"李文","vi":"Vậy lát nữa mình qua thăm cậu nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"现在路上车多，还下着雪，我开慢一点儿。\" (Bây giờ trên đường nhiều xe, trời lại đang có tuyết rơi, cô lái chậm một chút), nên đó là nguyên nhân cô Vương lái xe chậm.","options":["因为路上的车很多，而且在下雪","因为她不知道医院怎么走","因为她在接李文的电话","因为白家月说头越来越疼"],"q":"王老师为什么把车开得慢一点儿？"},{"answerIdx":1,"explanation":"Trong bài, khi nghe Bạch Gia Nguyệt nói đang đi bệnh viện vì đau đầu, Lý Văn liền trả lời \"那我一会儿去看看你。\" (Vậy lát nữa mình qua thăm cậu nhé).","options":["去学校帮她请假","过一会儿去看望白家月","给白家月买点儿水果","请王老师帮忙买药"],"q":"李文知道白家月去医院以后，打算怎么做？"}],"scene":"在王一飞车里，王一飞和白家月在聊天儿，李文打来一个电话。","sceneVi":"Trong xe của Vương Nhất Phi, Vương Nhất Phi và Bạch Gia Nguyệt đang trò chuyện thì Lý Văn gọi điện tới."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李文，快请进！","pinyin":"Lǐ Wén, kuài qǐng jìn!","speaker":"白家月","vi":"Lý Văn, mau vào đi!"},{"hanzi":"家月，你怎么样了？头还疼吗？","pinyin":"Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?","speaker":"李文","vi":"Gia Nguyệt, cậu sao rồi? Đầu còn đau không?"},{"hanzi":"不那么疼了。医生开了一些药，吃完就好多了。","pinyin":"Bú nàme téng le. Yīshēng kāile yìxiē yào, chīwán jiù hǎoduō le.","speaker":"白家月","vi":"Không đau như trước nữa rồi. Bác sĩ kê cho một ít thuốc, uống xong là đỡ hơn nhiều rồi."},{"hanzi":"那就好！","pinyin":"Nà jiù hǎo!","speaker":"李文","vi":"Thế thì tốt quá!"},{"hanzi":"家月，你想不想吃点儿东西？","pinyin":"Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?","speaker":"王一飞","vi":"Gia Nguyệt, em có muốn ăn chút gì không?"},{"hanzi":"吃点儿吧，身体不舒服时更要好好吃饭。","pinyin":"Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎohāo chī fàn.","speaker":"李文","vi":"Ăn chút đi, lúc cơ thể không khỏe càng phải ăn uống đàng hoàng."},{"hanzi":"吃点儿什么呢？","pinyin":"Chī diǎnr shénme ne?","speaker":"白家月","vi":"Ăn món gì bây giờ ạ?"},{"hanzi":"你最喜欢吃中国菜，我做几个中国菜吧。","pinyin":"Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ gè Zhōngguó cài ba.","speaker":"王一飞","vi":"Em thích ăn món Trung Quốc nhất, để cô nấu vài món Trung Quốc nhé."},{"hanzi":"好的，谢谢王老师。","pinyin":"Hǎo de, xièxie Wáng lǎoshī.","speaker":"白家月","vi":"Vâng ạ, cảm ơn cô Vương."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt trả lời Lý Văn \"不那么疼了。医生开了一些药，吃完就好多了。\" (Không đau như trước nữa rồi. Bác sĩ kê cho một ít thuốc, uống xong thì đỡ nhiều rồi).","options":["因为她喝了很多热茶","因为她睡了一整天","因为她吃了医生开的药","因为李文带她去外面散步"],"q":"白家月的头为什么没有以前那么疼了？"},{"answerIdx":0,"explanation":"Trong bài, cô Vương Nhất Phi nói với Bạch Gia Nguyệt \"你最喜欢吃中国菜，我做几个中国菜吧。\" (Em thích ăn món Trung Quốc nhất, cô làm vài món Trung Quốc nhé), nên đáp án đúng là 几个中国菜.","options":["几个中国菜","一碗面条","几个面包","一点儿水果"],"q":"王一飞老师打算给白家月做什么吃的？"}],"scene":"在房间，李文来看望白家月。","sceneVi":"Trong phòng, Lý Văn đến thăm Bạch Gia Nguyệt."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我这几天经常头疼，从药店买了点儿药，没去医院。","pinyin":"Wǒ zhè jǐ tiān jīngcháng tóu téng, cóng yàodiàn mǎile diǎnr yào, méi qù yīyuàn.","speaker":"Đoạn văn","vi":"Mấy hôm nay tôi thường xuyên bị đau đầu, đã mua một ít thuốc ở hiệu thuốc chứ không đi bệnh viện."},{"hanzi":"今天下课后，王老师看我不舒服，就送我去医院了。","pinyin":"Jīntiān xiàkè hòu, Wáng lǎoshī kàn wǒ bù shūfu, jiù sòng wǒ qù yīyuàn le.","speaker":"Đoạn văn","vi":"Hôm nay sau khi tan học, cô Vương thấy tôi không khỏe nên đã đưa tôi đến bệnh viện."},{"hanzi":"从医院回来，李文也来看我了。","pinyin":"Cóng yīyuàn huílái, Lǐ Wén yě lái kàn wǒ le.","speaker":"Đoạn văn","vi":"Từ bệnh viện trở về, Lý Văn cũng đã đến thăm tôi."},{"hanzi":"现在他们都回去了，我也要睡觉了。","pinyin":"Xiànzài tāmen dōu huíqù le, wǒ yě yào shuìjiào le.","speaker":"Đoạn văn","vi":"Bây giờ họ đều đã về rồi, tôi cũng chuẩn bị đi ngủ đây."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我这几天经常头疼，从药店买了点儿药，没去医院。\" (Mấy hôm nay tôi thường xuyên đau đầu, mua chút thuốc ở hiệu thuốc chứ không đi bệnh viện), nên trước hôm nay cô ấy tự mua thuốc ở hiệu thuốc.","options":["天天去医院看医生","自己从药店买了点儿药","在家休息，什么药也没吃","让李文开车送她去医院"],"q":"今天以前，白家月头疼的时候做了什么？"},{"answerIdx":2,"explanation":"Ở câu cuối nhật ký, Bạch Gia Nguyệt viết \"现在他们都回去了，我也要睡觉了。\" (Bây giờ mọi người đều về hết rồi, tôi cũng phải đi ngủ đây), nên cô ấy chuẩn bị đi ngủ.","options":["再吃一次药","出去送李文回家","上床睡觉","给王老师打电话"],"q":"写日记的时候，白家月接下来打算做什么？"}],"scene":"在房间，白家月在写日记。","sceneVi":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk2-12":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"喂，家月，是你啊！有什么事情吗？","pinyin":"Wèi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?","speaker":"王一雪","vi":"Alo, Gia Nguyệt à, là cháu đấy à! Có chuyện gì thế?"},{"hanzi":"没什么事，就想跟您说说话。","pinyin":"Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.","speaker":"白家月","vi":"Không có chuyện gì đâu ạ, cháu chỉ muốn trò chuyện với cô một chút thôi."},{"hanzi":"好啊。你今天没课吗？","pinyin":"Hǎo a. Nǐ jīntiān méi kè ma?","speaker":"王一雪","vi":"Được chứ. Hôm nay cháu không có tiết học à?"},{"hanzi":"下午有课。您那里天气怎么样？","pinyin":"Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?","speaker":"白家月","vi":"Buổi chiều cháu có tiết ạ. Thời tiết ở chỗ cô thế nào ạ?"},{"hanzi":"北京这几天虽然是晴天，但是有点儿冷。","pinyin":"Běijīng zhè jǐ tiān suīrán shì qíng tiān, dànshì yǒudiǎnr lěng.","speaker":"王一雪","vi":"Bắc Kinh mấy hôm nay tuy là trời nắng nhưng hơi lạnh một chút."},{"hanzi":"我这里比北京冷多了，外边还正下着雪呢！","pinyin":"Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!","speaker":"白家月","vi":"Ở chỗ cháu lạnh hơn Bắc Kinh nhiều lắm, bên ngoài trời còn đang rơi tuyết nữa cơ!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói \"北京这几天虽然是晴天，但是有点儿冷。\" (Bắc Kinh mấy hôm nay tuy trời nắng nhưng hơi lạnh), nên đáp án đúng là 是晴天，但是有点儿冷.","options":["是晴天，但是有点儿冷","一直阴天，还下着雪","很热，天天都是大晴天","刮大风，也下了雨"],"q":"北京这几天的天气怎么样？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我这里比北京冷多了，外边还正下着雪呢！\" (Chỗ cháu lạnh hơn Bắc Kinh nhiều, bên ngoài trời còn đang có tuyết rơi nữa!), nên đáp án đúng là 比北京冷多了，而且正在下雪.","options":["比北京暖和多了","和北京一样冷","比北京冷多了，而且正在下雪","没有北京那么冷，但是下雨了"],"q":"跟北京比，白家月那里的天气怎么样？"}],"scene":"在房间，王一雪接到白家月的电话。","sceneVi":"Trong phòng, Vương Nhất Tuyết nhận được cuộc gọi từ Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"喂，一飞，听家月说你那边下雪了，下得大不大？","pinyin":"Wèi, Yīfēi, tīng Jiāyuè shuō nǐ nàbiān xià xuě le, xià de dà bu dà?","speaker":"王一雪","vi":"Alo, Nhất Phi à, nghe Gia Nguyệt nói bên chỗ em có tuyết rơi rồi, rơi có to không?"},{"hanzi":"今天不大，昨天比今天下得大。","pinyin":"Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà.","speaker":"王一飞","vi":"Hôm nay không to lắm, hôm qua rơi to hơn hôm nay."},{"hanzi":"天气不好，你去外面的时候多穿点儿衣服。","pinyin":"Tiānqì bù hǎo, nǐ qù wàimiàn de shíhou duō chuān diǎnr yīfu.","speaker":"王一雪","vi":"Thời tiết không tốt, khi ra ngoài em nhớ mặc thêm nhiều quần áo vào nhé."},{"hanzi":"这几天我在网上上课，没出去过。","pinyin":"Zhè jǐ tiān wǒ zài wǎngshang shàngkè, méi chūqùguo.","speaker":"王一飞","vi":"Mấy hôm nay em dạy học trực tuyến nên chưa ra ngoài lần nào."},{"hanzi":"那就好，有事记得给我打电话。","pinyin":"Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà.","speaker":"王一雪","vi":"Thế thì tốt rồi, có việc gì nhớ gọi điện cho chị nhé."},{"hanzi":"好的。现在不下雪了，我出去买点儿吃的。","pinyin":"Hǎo de. Xiànzài bú xià xuě le, wǒ chūqù mǎi diǎnr chī de.","speaker":"王一飞","vi":"Vâng ạ. Bây giờ hết tuyết rơi rồi, em ra ngoài mua chút đồ ăn."},{"hanzi":"一次多买点儿，阴天下雪什么的就少出去吧。","pinyin":"Yí cì duō mǎi diǎnr, yīn tiān xià xuě shénmede jiù shǎo chūqù ba.","speaker":"王一雪","vi":"Mua một lần nhiều một chút, trời âm u hay tuyết rơi thì hạn chế ra ngoài nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Phi giải thích \"这几天我在网上上课，没出去过。\" (Mấy hôm nay em dạy học trên mạng, chưa từng ra ngoài), nên đáp án đúng là 因为她在网上上课.","options":["因为她在网上上课","因为她的车坏了","因为她生病了，头疼","因为家里有很多吃的"],"q":"王一飞这几天为什么没出去过？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết dặn dò \"一次多买点儿，阴天下雪什么的就少出去吧。\" (Mua nhiều một chút trong một lần, trời âm u hay tuyết rơi thì ít ra ngoài thôi), nên đáp án đúng là 一次多买点儿，天气不好时少出去.","options":["顺便买一件新衣服","坐地铁去超市，别开车","一次多买点儿，天气不好时少出去","买完吃的马上给家月打电话"],"q":"王一雪让王一飞去买东西的时候注意什么？"}],"scene":"在客厅，王一雪给王一飞打电话。","sceneVi":"Trong phòng khách, Vương Nhất Tuyết gọi điện thoại cho Vương Nhất Phi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，家月，今天天气不错，我们去跑步吧！","pinyin":"Wèi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!","speaker":"李文","vi":"Alo, Gia Nguyệt à, hôm nay thời tiết khá đẹp, chúng mình đi chạy bộ đi!"},{"hanzi":"你跑步跑得比我快，我们能一起跑吗？","pinyin":"Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?","speaker":"白家月","vi":"Cậu chạy bộ nhanh hơn mình, chúng mình có chạy cùng nhau được không?"},{"hanzi":"可以的，我慢慢跑，等着你。","pinyin":"Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ.","speaker":"李文","vi":"Được chứ, mình chạy chầm chậm rồi đợi cậu."},{"hanzi":"好吧。你真爱跑步啊！","pinyin":"Hǎo ba. Nǐ zhēn ài pǎobù a!","speaker":"白家月","vi":"Được thôi. Cậu đúng là thích chạy bộ thật đấy!"},{"hanzi":"我从小就经常跟爸爸跑步，跑步能让人快乐！","pinyin":"Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!","speaker":"李文","vi":"Từ nhỏ mình đã thường xuyên chạy bộ cùng bố, chạy bộ có thể khiến người ta vui vẻ!"},{"hanzi":"好，那我准备一下。","pinyin":"Hǎo, nà wǒ zhǔnbèi yíxià.","speaker":"白家月","vi":"Ừ, vậy để mình chuẩn bị một chút."},{"hanzi":"我现在坐地铁去找你，一会儿楼下见。","pinyin":"Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóu xià jiàn.","speaker":"李文","vi":"Bây giờ mình đi tàu điện ngầm qua tìm cậu, lát nữa gặp dưới tòa nhà nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"今天天气不错，我们去跑步吧！\" (Hôm nay thời tiết đẹp đấy, chúng ta đi chạy bộ đi!) và giải thích \"跑步能让人快乐！\" (Chạy bộ có thể khiến người ta vui vẻ!).","options":["因为今天天气不错，而且他觉得跑步能让人快乐","因为他们明天有跑步比赛","因为李文想早点儿去学校","因为家月请他教自己跑步"],"q":"李文为什么邀请白家月一起去跑步？"},{"answerIdx":1,"explanation":"Ở câu cuối bài, Lý Văn nói \"我现在坐地铁去找你，一会儿楼下见。\" (Bây giờ mình đi tàu điện ngầm qua chỗ cậu, lát nữa gặp nhau dưới lầu nhé), nên phương tiện là tàu điện ngầm và điểm hẹn là dưới lầu.","options":["他走路去，在学校门口见","他坐地铁去，在楼下见","他开车去，在公园里见","他坐公交车去，在教室见"],"q":"李文怎么去找白家月，两个人在哪儿见面？"}],"scene":"在房间，李文给白家月打电话。","sceneVi":"Trong phòng, Lý Văn gọi điện thoại cho Bạch Gia Nguyệt."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"前几天天气不好，我没走路，每天坐两站地铁去学校。","pinyin":"Qián jǐ tiān tiānqì bù hǎo, wǒ méi zǒulù, měitiān zuò liǎng zhàn dìtiě qù xuéxiào.","speaker":"Đoạn văn","vi":"Mấy hôm trước thời tiết không tốt, tôi không đi bộ mà mỗi ngày đi tàu điện ngầm hai trạm đến trường."},{"hanzi":"今天是个大晴天，李文让我跟他去外面跑步。","pinyin":"Jīntiān shì gè dà qíng tiān, Lǐ Wén ràng wǒ gēn tā qù wàimiàn pǎobù.","speaker":"Đoạn văn","vi":"Hôm nay là một ngày nắng đẹp, Lý Văn rủ tôi cùng cậu ấy ra ngoài chạy bộ."},{"hanzi":"他小时候经常跑步，跑得比我快，但是他会等我。","pinyin":"Tā xiǎoshíhou jīngcháng pǎobù, pǎo de bǐ wǒ kuài, dànshì tā huì děng wǒ.","speaker":"Đoạn văn","vi":"Hồi nhỏ cậu ấy thường xuyên chạy bộ, chạy nhanh hơn tôi, nhưng cậu ấy sẽ đợi tôi."},{"hanzi":"跟李文一起跑步，我好高兴啊！","pinyin":"Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!","speaker":"Đoạn văn","vi":"Chạy bộ cùng Lý Văn, tôi vui lắm!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"前几天天气不好，我没走路，每天坐两站地铁去学校。\" (Mấy hôm trước thời tiết không tốt, tôi không đi bộ mà mỗi ngày đi hai trạm tàu điện ngầm đến trường).","options":["坐两站地铁去学校","走路去学校","跟李文一起跑步去","坐王老师的车去"],"q":"前几天天气不好的时候，白家月怎么去学校？"},{"answerIdx":1,"explanation":"Ở câu cuối nhật ký, Bạch Gia Nguyệt viết \"跟李文一起跑步，我好高兴啊！\" (Chạy bộ cùng Lý Văn, tôi vui lắm!), nên cảm nhận của cô là rất vui.","options":["觉得太累了","觉得非常高兴","觉得天气还是有点儿冷","觉得自己跑得比李文快"],"q":"今天跟李文一起跑步，白家月觉得怎么样？"}],"scene":"在房间，白家月在写日记。","sceneVi":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk2-13":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"时间过得真快啊！新年就要到了。","pinyin":"Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le.","speaker":"白家月","vi":"Thời gian trôi qua thật nhanh! Năm mới sắp đến rồi."},{"hanzi":"这一年王老师教我们中文，每天工作都很累。","pinyin":"Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měi tiān gōngzuò dōu hěn lèi.","speaker":"陈天中","vi":"Một năm qua cô Vương dạy chúng ta tiếng Trung, ngày nào làm việc cũng rất mệt."},{"hanzi":"是啊，她教得很好。因为她，我们都非常爱上中文课。","pinyin":"Shì a, tā jiāo de hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè.","speaker":"白家月","vi":"Đúng vậy, cô ấy dạy rất hay. Vì cô ấy, chúng ta đều rất thích đi học tiết tiếng Trung."},{"hanzi":"我们给她准备个新年礼物吧。你觉得送给她什么好呢？","pinyin":"Wǒmen gěi tā zhǔnbèi gè xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?","speaker":"陈天中","vi":"Chúng ta chuẩn bị cho cô ấy một món quà năm mới đi. Bạn thấy tặng cô ấy cái gì thì tốt nhỉ?"},{"hanzi":"王老师喜欢花，就送给她花吧。","pinyin":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","speaker":"白家月","vi":"Cô Vương thích hoa, vậy tặng cô ấy hoa đi."},{"hanzi":"那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。","pinyin":"Nà wǒmen qù huādiàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huādiàn hái yǒu piàoliang de huā.","speaker":"陈天中","vi":"Vậy chúng ta đến tiệm hoa xem thử đi, bây giờ người mua hoa đông, hy vọng tiệm hoa vẫn còn hoa đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"王老师喜欢花，就送给她花吧。\" (Cô Vương thích hoa, vậy thì tặng hoa cho cô đi) và Trần Thiên Trung đồng ý, nên món quà họ muốn tặng là hoa.","options":["一个新本子","一些花","一个咖啡杯","一些中文书"],"q":"同学们想给王老师准备什么新年礼物？"},{"answerIdx":2,"explanation":"Ở cuối bài, Trần Thiên Trung nói \"那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。\" (Vậy chúng ta đến tiệm hoa xem thử đi, bây giờ người mua hoa nhiều, hy vọng tiệm hoa vẫn còn hoa đẹp).","options":["去办公室找王老师","去超市买咖啡","去花店看看","去书店买礼物"],"q":"说完以后，白家月和陈天中打算去哪儿？"}],"scene":"在教室，白家月和陈天中在聊天儿。","sceneVi":"Trong lớp học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"王老师，今天的词比昨天多了十个。","pinyin":"Wáng lǎoshī, jīntiān de cí bǐ zuótiān duōle shí gè.","speaker":"白家月","vi":"Cô Vương ơi, từ vựng hôm nay nhiều hơn hôm qua mười từ."},{"hanzi":"是啊！你们都学会了吗？","pinyin":"Shì a! Nǐmen dōu xuéhuìle ma?","speaker":"王一飞","vi":"Đúng vậy! Các em đều học thuộc hết chưa?"},{"hanzi":"学会了，没有问题。","pinyin":"Xuéhuì le, méiyǒu wèntí.","speaker":"安妮","vi":"Học được rồi ạ, không có vấn đề gì."},{"hanzi":"好。现在我来说，你们在本子上面写。","pinyin":"Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmiàn xiě.","speaker":"王一飞","vi":"Tốt. Bây giờ cô đọc, các em viết lên vở nhé."},{"hanzi":"同学们，“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。","pinyin":"Tóngxuémen, “xǐshǒujiān” de “jiān” zì xiěcuò le, tā de lǐmiàn shì “rì”, bú shì “kǒu”.","speaker":"王一飞","vi":"Các em ơi, chữ “间” trong từ “洗手间” (nhà vệ sinh) viết sai rồi, bên trong nó là chữ “日”, không phải chữ “口”."},{"hanzi":"“日”比“口”多一笔，写“口”就是“问题”的“问”了。","pinyin":"“Rì” bǐ “kǒu” duō yì bǐ, xiě “kǒu” jiù shì “wèntí” de “wèn” le.","speaker":"白家月","vi":"Chữ “日” nhiều hơn chữ “口” một nét, viết chữ “口” thì thành chữ “问” trong “问题” (vấn đề) rồi."},{"hanzi":"没错，你说得很对。","pinyin":"Méi cuò, nǐ shuō de hěn duì.","speaker":"王一飞","vi":"Không sai, em nói rất đúng."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"王老师，今天的词比昨天多了十个。\" (Thưa cô Vương, từ mới hôm nay nhiều hơn hôm qua mười từ), nên đáp án đúng là 比昨天多了十个.","options":["比昨天少了十个","比昨天多了十个","比昨天的词难多了","跟昨天的一样多"],"q":"今天要学的词跟昨天比有什么不一样？"},{"answerIdx":0,"explanation":"Trong bài, cô Vương nhắc \"“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。\" (Chữ \"间\" trong \"洗手间\" viết sai rồi, bên trong là \"日\" chứ không phải \"口\"), và Bạch Gia Nguyệt nói thêm nếu viết \"口\" thì thành chữ \"问\" trong \"问题\".","options":["把“洗手间”的“间”写成了“问”","把“问题”的“问”写成了“间”","把“洗手间”的“手”写错了","把“十个”的“十”写错了"],"q":"写汉字的时候，同学们把哪个字写错了？"}],"scene":"在教室，王一飞在上课。","sceneVi":"Trong lớp học, Vương Nhất Phi đang giảng bài."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"家月，你觉得这个本子怎么样？","pinyin":"Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?","speaker":"安妮","vi":"Gia Nguyệt, bạn thấy quyển vở này thế nào?"},{"hanzi":"很漂亮，多少钱一个？","pinyin":"Hěn piàoliang, duōshao qián yí gè?","speaker":"白家月","vi":"Đẹp lắm, bao nhiêu tiền một quyển vậy?"},{"hanzi":"比我们一起买的那个本子贵一点儿。","pinyin":"Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr.","speaker":"安妮","vi":"Đắt hơn quyển vở chúng ta cùng mua một chút."},{"hanzi":"这么漂亮的本子，不可能贵一点儿吧？","pinyin":"Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?","speaker":"白家月","vi":"Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút được chứ?"},{"hanzi":"我是上网买的，真没那么贵。我买了两个，送你一个。","pinyin":"Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎile liǎng gè, sòng nǐ yí gè.","speaker":"安妮","vi":"Mình mua trên mạng đấy, thật sự không đắt thế đâu. Mình mua hai quyển, tặng bạn một quyển."},{"hanzi":"谢谢！那我送给你什么呢？","pinyin":"Xièxie! Nà wǒ sòng gěi nǐ shénme ne?","speaker":"白家月","vi":"Cảm ơn bạn! Vậy mình tặng lại bạn cái gì nhỉ?"},{"hanzi":"咖啡杯吧，我最喜欢喝咖啡了。","pinyin":"Kāfēibēi ba, wǒ zuì xǐhuan hē kāfēi le.","speaker":"安妮","vi":"Cốc cà phê đi, mình thích uống cà phê nhất mà."},{"hanzi":"好，那样我们就都有新年礼物了！","pinyin":"Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","speaker":"白家月","vi":"Được, như vậy cả hai chúng ta đều có quà năm mới rồi!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, An Ni nói \"我是上网买的，真没那么贵。\" (Mình mua trên mạng đấy, thật sự không đắt thế đâu), nên đáp án đúng là 在网上买的.","options":["在学校旁边的商店","和家月一起去买的","在网上买的","从老师那里买的"],"q":"安妮的这个新本子是在哪儿买的？"},{"answerIdx":3,"explanation":"Trong bài, khi Bạch Gia Nguyệt hỏi nên tặng lại món gì, An Ni trả lời \"咖啡杯吧，我最喜欢喝咖啡了。\" (Cốc cà phê đi, mình thích uống cà phê nhất đấy), nên đáp án đúng là 一个咖啡杯.","options":["一个新本子","一杯奶茶","一些漂亮的花","一个咖啡杯"],"q":"安妮希望白家月送给她什么新年礼物？"}],"scene":"在教室，安妮和白家月在聊天儿。","sceneVi":"Trong lớp học, An Ni và Bạch Gia Nguyệt đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"新年就要到了，安妮送给我一个新本子。","pinyin":"Xīnnián jiù yào dào le, Ānnī sòng gěi wǒ yí gè xīn běnzi.","speaker":"Đoạn văn","vi":"Năm mới sắp đến rồi, An Ni tặng cho tôi một quyển vở mới."},{"hanzi":"她告诉我是在网上买的，比我的本子贵一点儿。","pinyin":"Tā gàosu wǒ shì zài wǎngshang mǎi de, bǐ wǒ de běnzi guì yìdiǎnr.","speaker":"Đoạn văn","vi":"Cô ấy nói với tôi là mua trên mạng, đắt hơn quyển vở của tôi một chút."},{"hanzi":"我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。","pinyin":"Wǒmen bān tóngxué yě sòngle Wáng lǎoshī piàoliang de huā, xīwàng tā gāogāoxìngxìng de guò gè xīnnián.","speaker":"Đoạn văn","vi":"Các bạn học lớp chúng tôi cũng đã tặng cô Vương hoa đẹp, mong cô đón một năm mới thật vui vẻ."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"她告诉我是在网上买的，比我的本子贵一点儿。\" (Cậu ấy bảo với tôi là mua trên mạng, đắt hơn quyển vở của tôi một chút), nên giá quyển vở mới đắt hơn vở của Bạch Gia Nguyệt một chút.","options":["比白家月的本子贵一点儿","比白家月的本子便宜多了","跟白家月的本子一样贵","非常贵，要很多钱"],"q":"安妮送给白家月的新本子价钱怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。\" (Các bạn trong lớp chúng tôi cũng tặng cô Vương hoa đẹp, mong cô đón một năm mới thật vui vẻ), nên lý do là mong cô đón năm mới vui vẻ.","options":["因为王老师最喜欢买花","因为今天是王老师的生日","因为希望王老师开开心心地过新年","因为王老师生病了，同学们去看她"],"q":"同学们为什么送给王老师漂亮的花？"}],"scene":"在房间，白家月在写日记。","sceneVi":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk2-14":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"王老师，你家楼下站着一个人。","pinyin":"Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí gè rén.","speaker":"李文","vi":"Cô Vương ơi, dưới tòa nhà của cô có một người đang đứng."},{"hanzi":"我家楼下？我看看。","pinyin":"Wǒ jiā lóu xià? Wǒ kànkan.","speaker":"王一飞","vi":"Dưới tòa nhà của tôi à? Để tôi xem thử."},{"hanzi":"那个人穿着黑色的裤子，手里还拿着一个黑色的包。","pinyin":"Nàge rén chuānzhe hēisè de kùzi, shǒuli hái názhe yí gè hēisè de bāo.","speaker":"李文","vi":"Người đó mặc chiếc quần màu đen, trong tay còn cầm một chiếc túi màu đen."},{"hanzi":"我看见那个人了，他是我男朋友。","pinyin":"Wǒ kànjiàn nàge rén le, tā shì wǒ nánpéngyou.","speaker":"王一飞","vi":"Tôi nhìn thấy người đó rồi, anh ấy là bạn trai của tôi."},{"hanzi":"那我们快过去吧。","pinyin":"Nà wǒmen kuài guòqù ba.","speaker":"李文","vi":"Vậy chúng ta mau qua đó đi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"王老师，你家楼下站着一个人。\" (Thầy/cô Vương ơi, dưới tòa nhà nhà thầy/cô có một người đang đứng.), nên đáp án đúng là dưới tòa nhà nhà thầy/cô Vương.","options":["王老师家楼下","李文家楼下","学校的门口","回家路上的商店里"],"q":"李文看见那个人站在哪儿？"},{"answerIdx":2,"explanation":"Trong bài có câu \"那个人穿着黑色的裤子，手里还拿着一个黑色的包。\" (Người đó mặc quần màu đen, trong tay còn cầm một chiếc túi màu đen.) và \"他是我男朋友。\" (Anh ấy là bạn trai của tôi.), nên đáp án đúng là bạn trai của Vương Nhất Phi, tay cầm một chiếc túi màu đen.","options":["王一飞的哥哥，拿着一件黑色的衣服","李文的朋友，拿着一双黑色的鞋","王一飞的男朋友，拿着一个黑色的包","王一飞的同事，拿着一本书"],"q":"楼下站着的那个人是谁？他手里拿着什么？"}],"scene":"在回家路上，李文和王一飞边走边聊。","sceneVi":"Trên đường về nhà, Lý Văn và Vương Nhất Phi vừa đi vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"同乐，真是你啊！上次打电话，你说有时间过来看我，没想到这么快就来了！","pinyin":"Tónglè, zhēn shì nǐ a! Shàng cì dǎ diànhuà, nǐ shuō yǒu shíjiān guòlái kàn wǒ, méi xiǎngdào zhème kuài jiù lái le!","speaker":"王一飞","vi":"Đồng Nhạc, đúng là anh rồi! Lần trước gọi điện thoại, anh nói có thời gian sẽ qua thăm em, không ngờ nhanh thế đã đến rồi!"},{"hanzi":"就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。","pinyin":"Jiù yào guònián le, nǐ yí gè rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎozǎo guòlái le.","speaker":"杨同乐","vi":"Sắp đến Tết rồi, em ở đây một mình chán biết bao nhiêu, vì thế anh đã qua đây sớm."},{"hanzi":"你能来，我太高兴了！","pinyin":"Nǐ néng lái, wǒ tài gāoxìng le!","speaker":"王一飞","vi":"Anh đến được, em vui quá đi mất!"},{"hanzi":"一飞，你旁边这位是？","pinyin":"Yīfēi, nǐ pángbiān zhè wèi shì?","speaker":"杨同乐","vi":"Nhất Phi, vị bên cạnh em đây là ai vậy?"},{"hanzi":"同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。","pinyin":"Tónglè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tónglè.","speaker":"王一飞","vi":"Đồng Nhạc, đây là Lý Văn, cậu ấy học ngành y ở trường chúng ta. Lý Văn, đây là bạn trai tôi Dương Đồng Nhạc."},{"hanzi":"李文，很高兴认识你！","pinyin":"Lǐ Wén, hěn gāoxìng rènshi nǐ!","speaker":"杨同乐","vi":"Lý Văn, rất vui được làm quen với bạn!"},{"hanzi":"认识你我也很高兴！我家就在前面那个楼，有时间来玩。","pinyin":"Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmiàn nàge lóu, yǒu shíjiān lái wán.","speaker":"李文","vi":"Làm quen với anh tôi cũng rất vui! Nhà tôi ở ngay tòa nhà phía trước kia, có thời gian ghé chơi nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。\" (Sắp đón năm mới rồi, em ở đây một mình buồn tẻ lắm, nên anh liền qua sớm.), nên đáp án đúng là vì sắp đón năm mới và sợ Vương Nhất Phi ở một mình buồn chán.","options":["因为他要来这个学校学习医学","因为快要过年了，怕王一飞一个人没意思","因为王一飞生病了，请他来照顾自己","因为他正好在前面那个楼有工作"],"q":"杨同乐为什么这么早过来看王一飞？"},{"answerIdx":3,"explanation":"Trong bài có câu \"这是李文，他在我们学校学医。\" (Đây là Lý Văn, cậu ấy học y ở trường chúng tôi.) và \"我家就在前面那个楼\" (Nhà tôi ở ngay tòa nhà phía trước), nên đáp án đúng là Lý Văn học y ở trường của Vương Nhất Phi và nhà ở tòa nhà phía trước.","options":["李文和杨同乐是好朋友","李文在王一飞的学校学中文","李文住在王一飞家后面那个楼","李文在王一飞的学校学医，家就在前面那个楼"],"q":"关于李文，下面哪句话是对的？"}],"scene":"在楼下，王一飞见到杨同乐。","sceneVi":"Ở dưới nhà, Vương Nhất Phi gặp Dương Đồng Nhạc."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"一飞，你住的房子真不错，很大，离学校也不远。","pinyin":"Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn.","speaker":"杨同乐","vi":"Nhất Phi, căn nhà em ở thật tuyệt, rất rộng, lại cách trường không xa."},{"hanzi":"是啊！我楼下还住着一家中国人，他们人很好。","pinyin":"Shì a! Wǒ lóu xià hái zhùzhe yì jiā Zhōngguó rén, tāmen rén hěn hǎo.","speaker":"王一飞","vi":"Đúng vậy! Tầng dưới nhà em còn có một gia đình người Trung Quốc ở, họ rất tốt bụng."},{"hanzi":"这样你有事情就可以找他们帮忙。","pinyin":"Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng.","speaker":"杨同乐","vi":"Như vậy khi em có việc thì có thể nhờ họ giúp đỡ."},{"hanzi":"对，我也帮他们家的小孩儿学中文。","pinyin":"Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","speaker":"王一飞","vi":"Đúng rồi, em cũng giúp em bé nhà họ học tiếng Trung."},{"hanzi":"我记得你跟我说过，是个女孩儿，学得也很好。","pinyin":"Wǒ jìde nǐ gēn wǒ shuōguo, shì gè nǚháir, xué de yě hěn hǎo.","speaker":"杨同乐","vi":"Anh nhớ em từng kể với anh rồi, là một bé gái, học cũng rất giỏi."},{"hanzi":"没错，她经常跑上来找我玩。","pinyin":"Méi cuò, tā jīngcháng pǎo shànglái zhǎo wǒ wán.","speaker":"王一飞","vi":"Không sai, cô bé thường chạy lên đây tìm em chơi."},{"hanzi":"你问问他们什么时候有时间，我请他们吃个饭。","pinyin":"Nǐ wènwen tāmen shénme shíhou yǒu shíjiān, wǒ qǐng tāmen chī gè fàn.","speaker":"杨同乐","vi":"Em hỏi họ xem khi nào có thời gian, anh mời họ ăn một bữa cơm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"一飞，你住的房子真不错，很大，离学校也不远。\" (Nhất Phi, căn nhà em ở thật tuyệt, rất rộng, cách trường cũng không xa.), nên đáp án đúng là căn nhà rất rộng và gần trường.","options":["房子有点儿小，但是很干净","房子很大，而且离学校很近","房子离学校很远，但是很安静","房子太旧了，不太方便"],"q":"杨同乐觉得王一飞住的房子怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我也帮他们家的小孩儿学中文。\" (Em cũng giúp em bé nhà họ học tiếng Trung.), nên đáp án đúng là giúp em bé tầng dưới học tiếng Trung.","options":["帮她做晚饭","帮她学唱歌和跳舞","帮她学中文","每天送她去学校"],"q":"王一飞经常帮楼下那家人的小孩儿做什么？"}],"scene":"在王一飞家里，王一飞和杨同乐在客厅聊天儿。","sceneVi":"Ở nhà Vương Nhất Phi, Vương Nhất Phi và Dương Đồng Nhạc đang trò chuyện trong phòng khách."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我男朋友姓杨，叫杨同乐。","pinyin":"Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè.","speaker":"Đoạn văn","vi":"Bạn trai tôi họ Dương, tên là Dương Đồng Nhạc."},{"hanzi":"他高个子、大眼睛，唱歌唱得很好，跳舞跳得也不错。","pinyin":"Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo, tiàowǔ tiào de yě búcuò.","speaker":"Đoạn văn","vi":"Anh ấy dáng cao, mắt to, hát rất hay, nhảy cũng khá giỏi."},{"hanzi":"他和我的姐姐一起工作，是姐姐介绍我们认识的。","pinyin":"Tā hé wǒ de jiějie yìqǐ gōngzuò, shì jiějie jièshào wǒmen rènshi de.","speaker":"Đoạn văn","vi":"Anh ấy làm việc cùng chị gái tôi, là chị gái đã giới thiệu chúng tôi quen nhau."},{"hanzi":"他告诉我，从见到我的第一天开始，他就喜欢上我了。","pinyin":"Tā gàosu wǒ, cóng jiàndào wǒ de dì-yī tiān kāishǐ, tā jiù xǐhuan shàng wǒ le.","speaker":"Đoạn văn","vi":"Anh ấy nói với tôi rằng, bắt đầu từ ngày đầu tiên gặp tôi, anh ấy đã thích tôi rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"他和我的姐姐一起工作，是姐姐介绍我们认识的。\" (Anh ấy làm việc cùng chị gái tôi, là chị gái đã giới thiệu chúng tôi quen nhau.), nên đáp án đúng là do chị gái của Vương Nhất Phi giới thiệu.","options":["在学校学中文的时候认识的","王一飞的姐姐介绍他们认识的","他们在一家饭馆吃饭的时候认识的","杨同乐搬到王一飞楼下后认识的"],"q":"王一飞和杨同乐是怎么认识的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"唱歌唱得很好，跳舞跳得也不错\" (hát rất hay, nhảy cũng rất khá) và \"从见到我的第一天开始，他就喜欢上我了\" (từ ngày đầu tiên gặp tôi, anh ấy đã thích tôi rồi), nên đáp án đúng là Dương Đồng Nhạc hát hay, nhảy giỏi và thích Vương Nhất Phi từ ngày đầu tiên gặp mặt.","options":["杨同乐个子不高，也不太会跳舞","杨同乐在认识王一飞很久以后才喜欢上她","杨同乐唱歌和跳舞都很好，第一天见王一飞就喜欢上她了","杨同乐和王一飞在同一个公司一起工作"],"q":"根据日记内容，下面哪句话是对的？"}],"scene":"在房间，王一飞在写日记。","sceneVi":"Trong phòng, Vương Nhất Phi đang viết nhật ký."}],"hsk2-15":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"考试就要开始了，请大家写上姓名，写好后就可以做题了。","pinyin":"Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiě shàng xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le.","speaker":"王一飞","vi":"Bài thi sắp bắt đầu rồi, mời mọi người viết họ tên vào, viết xong là có thể làm bài rồi."},{"hanzi":"老师，我做完了。","pinyin":"Lǎoshī, wǒ zuòwán le.","speaker":"白家月","vi":"Thưa cô, em làm xong rồi ạ."},{"hanzi":"老师，我也做完了。","pinyin":"Lǎoshī, wǒ yě zuòwán le.","speaker":"陈天中","vi":"Thưa cô, em cũng làm xong rồi ạ."},{"hanzi":"……对了，你们考完试想做什么？","pinyin":"……Duìle, nǐmen kǎowán shì xiǎng zuò shénme?","speaker":"王一飞","vi":"……À đúng rồi, các em thi xong muốn làm gì?"},{"hanzi":"我很想去中国，虽然去过一次，但是很想再去一次。","pinyin":"Wǒ hěn xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì.","speaker":"白家月","vi":"Em rất muốn đi Trung Quốc, tuy đã từng đi một lần rồi, nhưng rất muốn đi thêm lần nữa."},{"hanzi":"不错，到中国后你就可以经常说中文了。","pinyin":"Búcuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le.","speaker":"王一飞","vi":"Tốt lắm, sau khi đến Trung Quốc em có thể thường xuyên nói tiếng Trung rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"考试就要开始了，请大家写上姓名，写好后就可以做题了。\" (Kỳ thi sắp bắt đầu rồi, mời cả lớp viết họ tên vào, viết xong thì có thể làm bài.), nên đáp án đúng là viết họ tên của mình trước.","options":["先开始做题","先写上自己的姓名","先用中文介绍一下自己","先休息几分钟"],"q":"考试开始以前，王老师让大家先做什么？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我很想去中国，虽然去过一次，但是很想再去一次。\" (Em rất muốn đi Trung Quốc, tuy đã từng đi một lần nhưng rất muốn đi thêm lần nữa.), nên đáp án đúng là Bạch Gia Nguyệt từng đến Trung Quốc một lần và muốn đi lại sau khi thi xong.","options":["她从来没有去过中国","她以前去过一次中国，考完试还想再去一次","她觉得今天的考试题太难了，还没做完","她考完试不想去旅游，只想在学校学中文"],"q":"关于白家月，下面哪句话是对的？"}],"scene":"在教室，同学们在考试。","sceneVi":"Ở trong lớp học, các bạn học sinh đang làm bài thi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"考完试了，我现在可以出国旅游了。","pinyin":"Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le.","speaker":"白家月","vi":"Thi xong rồi, bây giờ mình có thể đi du lịch nước ngoài rồi."},{"hanzi":"你要去哪儿？","pinyin":"Nǐ yào qù nǎr?","speaker":"李文","vi":"Cậu định đi đâu thế?"},{"hanzi":"我要再去一次北京。","pinyin":"Wǒ yào zài qù yí cì Běijīng.","speaker":"白家月","vi":"Mình muốn đi Bắc Kinh thêm một lần nữa."},{"hanzi":"为什么还去北京？","pinyin":"Wèi shénme hái qù Běijīng?","speaker":"李文","vi":"Tại sao lại đi Bắc Kinh nữa thế?"},{"hanzi":"因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……","pinyin":"Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng……","speaker":"白家月","vi":"Vì mình muốn ăn vịt quay một lần nữa, uống trà sữa một lần nữa, rồi đến Đại học Bắc Kinh xem phim một lần nữa……"},{"hanzi":"你想做的事情很多啊！","pinyin":"Nǐ xiǎng zuò de shìqing hěn duō a!","speaker":"李文","vi":"Cậu muốn làm nhiều việc thật đấy!"},{"hanzi":"是啊，你看，我还在网上买好颐和园的门票了呢。","pinyin":"Shì a, nǐ kàn, wǒ hái zài wǎngshang mǎihǎo Yíhé Yuán de ménpiào le ne.","speaker":"白家月","vi":"Đúng vậy, cậu xem, mình còn mua sẵn vé vào Di Hòa Viên trên mạng rồi cơ đấy."},{"hanzi":"我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。","pinyin":"Wǒ de gāozhōng tóngxué jiù zài Yíhé Yuán shàngbān, kěyǐ ràng tā gěi nǐ hǎohǎo jièshào jièshào.","speaker":"李文","vi":"Bạn học cấp ba của mình làm việc ngay ở Di Hòa Viên, có thể nhờ cậu ấy giới thiệu kỹ cho cậu."},{"hanzi":"太好了！出门旅游，多个朋友多条路。","pinyin":"Tài hǎo le! Chūmén lǚyóu, duō gè péngyou duō tiáo lù.","speaker":"白家月","vi":"Tuyệt quá! Ra ngoài du lịch, thêm một người bạn là thêm một con đường."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài có câu \"因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……\" (Vì tôi muốn ăn vịt quay một lần nữa, uống trà sữa một lần nữa, đến Đại học Bắc Kinh xem phim một lần nữa...), không nhắc đến việc học tiếng Trung tại Đại học Bắc Kinh, nên đáp án đúng là \"去北京大学上中文课\".","options":["再吃一次烤鸭","再喝一次奶茶","去北京大学看一次电影","去北京大学上中文课"],"q":"下面哪件事不是白家月想再去北京做的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。\" (Bạn học cấp ba của tôi làm việc ở Di Hòa Viên, có thể nhờ cậu ấy giới thiệu kỹ cho bạn.), nên đáp án đúng là giới thiệu về Di Hòa Viên cho Bạch Gia Nguyệt.","options":["帮她在网上买颐和园的门票","带她去吃便宜又好吃的烤鸭","因为他在颐和园上班，可以好好给她介绍一下颐和园","去机场接她，送她去宾馆"],"q":"李文的高中同学能给白家月什么帮助？"}],"scene":"在咖啡店，李文和白家月在聊天儿。","sceneVi":"Ở quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李文，你有一年没回国了吧？","pinyin":"Lǐ Wén, nǐ yǒu yì nián méi huí guó le ba?","speaker":"白家月","vi":"Lý Văn, cậu đã một năm chưa về nước rồi nhỉ?"},{"hanzi":"不到一年。我六月的时候回去了一次。","pinyin":"Bú dào yì nián. Wǒ Liùyuè de shíhou huíqùle yí cì.","speaker":"李文","vi":"Chưa đến một năm đâu. Hồi tháng Sáu mình có về một lần."},{"hanzi":"我怎么忘了？还是我送你去的机场呢。","pinyin":"Wǒ zěnme wàng le? Hái shì wǒ sòng nǐ qù de jīchǎng ne.","speaker":"白家月","vi":"Sao mình lại quên được nhỉ? Chính mình còn tiễn cậu ra sân bay cơ mà."},{"hanzi":"是啊。","pinyin":"Shì a.","speaker":"李文","vi":"Đúng vậy."},{"hanzi":"我记得你那次的机票很便宜。","pinyin":"Wǒ jìde nǐ nà cì de jīpiào hěn piányi.","speaker":"白家月","vi":"Mình nhớ vé máy bay lần đó của cậu rất rẻ."},{"hanzi":"没错，可能因为那个时候去北京的人不多吧。","pinyin":"Méi cuò, kěnéng yīnwèi nàge shíhou qù Běijīng de rén bù duō ba.","speaker":"李文","vi":"Đúng rồi, có lẽ vì lúc đó không có nhiều người đi Bắc Kinh."},{"hanzi":"这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","pinyin":"Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de.","speaker":"白家月","vi":"Vé máy bay lần này tuy hơi đắt một chút, nhưng nghĩ đến việc sắp được bay đi Bắc Kinh rồi, mình vẫn thấy rất vui."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"不到一年。我六月的时候回去了一次。\" (Chưa đến một năm đâu. Tháng Sáu tôi đã về một lần rồi.), nên đáp án đúng là vào tháng Sáu.","options":["去年十二月","一年多以前","六月的时候","下个星期五"],"q":"李文上次是什么时候回国的？"},{"answerIdx":1,"explanation":"Trong bài có câu \"这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。\" (Vé máy bay lần này tuy hơi đắt một chút, nhưng nghĩ đến việc sắp được bay tới Bắc Kinh, tôi vẫn rất vui.), nên đáp án đúng là vé hơi đắt nhưng cô ấy vẫn rất vui.","options":["机票很便宜，所以她非常高兴","机票有点儿贵，但她还是很开心","机票太贵了，她决定不坐飞机去北京了","机票很贵，所以她不太高兴"],"q":"关于白家月这次去北京的机票和心情，下面哪句话是对的？"}],"scene":"在咖啡店，李文和白家月在聊天儿。","sceneVi":"Ở quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我六月的时候回过一次北京，现在有半年多没回去了，我有点儿想家。","pinyin":"Wǒ Liùyuè de shíhou huíguo yí cì Běijīng, xiànzài yǒu bàn nián duō méi huíqù le, wǒ yǒudiǎnr xiǎng jiā.","speaker":"Đoạn văn","vi":"Hồi tháng Sáu tôi có về Bắc Kinh một lần, đến nay đã hơn nửa năm chưa về rồi, tôi hơi nhớ nhà."},{"hanzi":"就要过年了，我要回家过年。","pinyin":"Jiù yào guònián le, wǒ yào huí jiā guònián.","speaker":"Đoạn văn","vi":"Sắp đón năm mới rồi, tôi muốn về nhà đón Tết."},{"hanzi":"家月这次也要去北京，我们都是星期五的飞机。","pinyin":"Jiāyuè zhè cì yě yào qù Běijīng, wǒmen dōu shì Xīngqīwǔ de fēijī.","speaker":"Đoạn văn","vi":"Gia Nguyệt lần này cũng muốn đi Bắc Kinh, chúng tôi đều đi chuyến bay thứ Sáu."},{"hanzi":"家月说我们好像小鸟，一起飞到北京，再一起飞回这里。","pinyin":"Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēidào Běijīng, zài yìqǐ fēihuí zhèlǐ.","speaker":"Đoạn văn","vi":"Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ, cùng nhau bay đến Bắc Kinh, rồi lại cùng nhau bay về đây."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"现在有半年多没回去了，我有点儿想家。就要过年了，我要回家过年。\" (Hiện tại đã hơn nửa năm chưa về rồi, tôi hơi nhớ nhà. Sắp đón năm mới rồi, tôi phải về nhà ăn Tết.), nên đáp án đúng là vì nhớ nhà và về quê đón năm mới.","options":["因为他要陪白家月去颐和园玩","因为他在北京找到了新的工作","因为他有半年多没回去了，有点儿想家，要回家过年","因为那时候去北京的机票非常便宜"],"q":"李文这次为什么回北京？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我们都是星期五的飞机。\" (Chúng tôi đều đi chuyến bay vào thứ Sáu.), nên đáp án đúng là thứ Sáu.","options":["星期五","星期六","六月的时候","下个月底"],"q":"李文和白家月什么时候坐飞机去北京？"}],"scene":"在房间，李文在写日记。","sceneVi":"Trong phòng, Lý Văn đang viết nhật ký."}]});
